    target_dir = Path(args.target)
    target_dir.mkdir(parents=True, exist_ok=True)

    state_file = target_dir / "integrity_state.json"

    if args.files:
        monitored_paths = [Path(f) for f in args.files]
    else:
        monitored_paths = [Path(f) for f in get_default_critical_files()]

    stored_checksums = {}
    if state_file.is_file():
        try:
            with open(state_file, "r") as f:
                stored_checksums = json.load(f)
        except json.JSONDecodeError:
            print("Warning: State file corrupted. Resetting baseline.")

    if not stored_checksums:
        print("Initial scan: Storing baseline checksums.")
        current_checksums = {}
        for path in monitored_paths:
            if path.is_file():
                checksum = compute_sha256(path)
                if checksum:
                    current_checksums[str(path)] = checksum
            else:
                print(f"Notice: Monitored file does not exist: {path}")

        with open(state_file, "w") as f:
            json.dump(current_checksums, f, indent=4)
        print("Baseline established successfully.")

        perform_required_simulations(target_dir, monitored_paths)
    else:
        print("Performing integrity check against baseline...")
        current_checksums = {}
        for path in monitored_paths:
            if path.is_file():
                checksum = compute_sha256(path)
                if checksum:
                    current_checksums[str(path)] = checksum
            else:
                print(f"Notice: Monitored file does not exist: {path}")

        changes_detected = False

        all_keys = set(stored_checksums.keys()).union(set(current_checksums.keys()))

        for key in sorted(all_keys):
            path = Path(key)
            stored_val = stored_checksums.get(key)
            current_val = current_checksums.get(key)

            if stored_val is None:
                print(f"[ADDED] New file detected: {path}")
                changes_detected = True
            elif current_val is None:
                print(f"[REMOVED] Monitored file is missing: {path}")
                changes_detected = True
            elif stored_val != current_val:
                print(f"[MODIFIED] Critical file content changed: {path}")
                changes_detected = True
            else:
                print(f"[OK] Unchanged: {path}")

        with open(state_file, "w") as f:
            json.dump(current_checksums, f, indent=4)

        if changes_detected:
            print("\nResult: Integrity violations detected.")
        else:
            print("\nResult: All critical files intact.")


