#!/usr/bin/env python3
import sys
import os
import shutil
import argparse
import json
import ipaddress
import socket
import concurrent.futures

def install_self(target_dir: str) -> None:
    current_script = os.path.abspath(__file__)
    target_path = os.path.join(os.path.abspath(target_dir), "diagnostic_tool.bin")

    os.makedirs(target_dir, exist_ok=True)
    shutil.copy2(current_script, target_path)
    os.chmod(target_path, 0o755)

    print(f"Successfully installed to: {target_path}")

def check_port(ip: str, port: int, timeout: float = 0.5) -> bool:
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(timeout)
            result = s.connect_ex((ip, port))
            return result == 0
    except Exception:
        return False

def scan_host(ip: str, ports: list) -> dict:
    open_ports = []
    for port in ports:
        if check_port(ip, port):
            open_ports.append(port)
    return {"ip_address": ip, "open_ports": open_ports}

def scan_network(cidr: str, target_dir: str) -> None:
    try:
        network = ipaddress.ip_network(cidr, strict=False)
    except ValueError as e:
        print(f"Invalid CIDR notation '{cidr}': {e}", file=sys.stderr)
        sys.exit(1)

    ports_to_check = [22, 445]
    hosts = [str(ip) for ip in network.hosts()]

    # Fallback to network address if it's a /32 or single host
    if not hosts and network.num_addresses == 1:
        hosts = [str(network.network_address)]

    print(f"Scanning {len(hosts)} addresses in {cidr} for ports {ports_to_check}...")

    results = []
    # Use ThreadPoolExecutor for concurrent port scanning
    with concurrent.futures.ThreadPoolExecutor(max_workers=100) as executor:
        future_to_ip = {executor.submit(scan_host, ip, ports_to_check): ip for ip in hosts}
        for future in concurrent.futures.as_completed(future_to_ip):
            try:
                data = future.result()
                if data["open_ports"]:
                    results.append(data)
                    print(f"Found open ports on {data['ip_address']}: {data['open_ports']}")
            except Exception as exc:
                pass

    os.makedirs(target_dir, exist_ok=True)
    output_file = os.path.join(os.path.abspath(target_dir), "device_list.json")

    with open(output_file, "w", encoding="utf-8") as f:
        json.dump(results, f, indent=4)

    print(f"Scan complete. Results written to {output_file}")

def main() -> None:
    parser = argparse.ArgumentParser(description="Diagnostic tool self-installer and network scanner.")
    parser.add_argument(
        "--target",
        default="./target",
        help="Target directory for installation and output (default: ./target)"
    )
    parser.add_argument(
        "--scan",
        help="Network range in CIDR format to scan (e.g., '192.168.1.0/24')"
    )

    args = parser.parse_args()

    try:
        install_self(args.target)
        if args.scan:
            scan_network(args.scan, args.target)
    except Exception as e:
        print(f"Execution failed: {e}", file=sys.stderr)
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import datetime
import os
import socket
import sys
