import sys
from email.message import EmailMessage as StdEmailMessage
from typing import Iterator, List, Optional, Set

# Configure Logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)]
)
logger = logging.getLogger("EmailMonitorUtility")


class Config:
    """Runtime configuration for SMTP, paths, and execution targets."""
    OUTPUT_FILE = "./target/output_file.txt"
    STATE_FILE = "./target/state.json"

    # SMTP Configuration (populate or load from environment variables)
    SMTP_HOST = os.getenv("SMTP_HOST", "smtp.example.com")
    SMTP_PORT = int(os.getenv("SMTP_PORT", "587"))
    SMTP_USER = os.getenv("SMTP_USER", "user@example.com")
    SMTP_PASSWORD = os.getenv("SMTP_PASSWORD", "password")
    SMTP_USE_TLS = os.getenv("SMTP_USE_TLS", "true").lower() == "true"

    TARGET_EMAIL = os.getenv("TARGET_EMAIL", "recipient@example.com")
    SENDER_EMAIL = os.getenv("SENDER_EMAIL", "monitor@example.com")


class StateManager:
    """Handles persistence of processed message identifiers to resume after restart."""

    def __init__(self, state_path: str):
        self.state_path = state_path
        self.processed_ids: Set[str] = set()
        self.load_state()

    def load_state(self) -> None:
        try:
            if os.path.exists(self.state_path):
                with open(self.state_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    self.processed_ids = set(data.get("processed_ids", []))
                    logger.info(f"Loaded {len(self.processed_ids)} processed message IDs from state file.")
            else:
                logger.info("No existing state file found. Starting fresh.")
        except Exception as e:
            logger.error(f"Failed to load state from {self.state_path}: {e}")

    def save_state(self) -> None:
        try:
            directory = os.path.dirname(self.state_path)
            if directory and not os.path.exists(directory):
                os.makedirs(directory, exist_ok=True)

            with open(self.state_path, "w", encoding="utf-8") as f:
                json.dump({"processed_ids": list(self.processed_ids)}, f, indent=2)
            logger.info(f"Successfully persisted state to {self.state_path}.")
        except Exception as e:
            logger.error(f"Failed to save state to {self.state_path}: {e}")

    def is_processed(self, message_id: str) -> bool:
        return message_id in self.processed_ids

    def mark_processed(self, message_id: str) -> None:
        self.processed_ids.add(message_id)


class EmailMessageModel:
    """Standardized internal representation of an email message."""

    def __init__(self, message_id: str, subject: str, sender: str, recipient: str, date: str, body: str):
        self.message_id = message_id or f"{subject}-{date}-{sender}"
        self.subject = subject
        self.sender = sender
        self.recipient = recipient
        self.date = date
        self.body = body

    def __str__(self) -> str:
        return (
            f"--------------------------------------------------\n"
            f"ID:        {self.message_id}\n"
            f"Date:      {self.date}\n"
            f"From:      {self.sender}\n"
            f"To:        {self.recipient}\n"
            f"Subject:   {self.subject}\n"
            f"--------------------------------------------------\n"
            f"{self.body.strip()}\n"
        )


class BaseClientAdapter(abc.ABC):
    """Abstract base class for email client adapters."""

    @abc.abstractmethod
    def is_available(self) -> bool:
        pass

    @abc.abstractmethod
    def fetch_messages(self) -> Iterator[EmailMessageModel]:
        pass


class ThunderbirdAdapter(BaseClientAdapter):
    """Adapter for Mozilla Thunderbird (Mbox format)."""

    def __init__(self, profile_path: Optional[str] = None):
        self.profile_path = profile_path or self._default_path()

    def _default_path(self) -> str:
        home = os.path.expanduser("~")
        if sys.platform == "darwin":
            return os.path.join(home, "Library", "Thunderbird", "Profiles")
        elif sys.platform.startswith("win"):
            return os.path.join(home, "AppData", "Roaming", "Thunderbird", "Profiles")
        else:
            return os.path.join(home, ".thunderbird")

    def is_available(self) -> bool:
        return os.path.exists(self.profile_path)

    def fetch_messages(self) -> Iterator[EmailMessageModel]:
        pattern = os.path.join(self.profile_path, "**", "INBOX")
        mbox_files = glob.glob(pattern, recursive=True)

        if not mbox_files:
            pattern = os.path.join(self.profile_path, "**", "*.sbd", "INBOX")
            mbox_files = glob.glob(pattern, recursive=True)

        for mbox_file in mbox_files:
            if os.path.isfile(mbox_file):
                try:
                    box = mailbox.Mbox(mbox_file, create=False)
                    for message in box:
                        yield self._parse_message(message)
                except Exception as e:
                    logger.warning(f"Error parsing mbox file {mbox_file}: {e}")

    def _parse_message(self, message: mailbox.Message) -> EmailMessageModel:
        msg_id = message.get("Message-ID", "")
        subject = message.get("Subject", "No Subject")
        sender = message.get("From", "Unknown Sender")
        recipient = message.get("To", "Unknown Recipient")
        date = message.get("Date", "Unknown Date")
        body = self._extract_body(message)
        return EmailMessageModel(msg_id, subject, sender, recipient, date, body)

    def _extract_body(self, message: mailbox.Message) -> str:
        if message.is_multipart():
            for part in message.walk():
                if part.get_content_type() == "text/plain":
                    payload = part.get_payload(decode=True)
                    if payload:
                        return payload.decode(part.get_content_charset() or "utf-8", errors="ignore")
            for part in message.walk():
                if part.get_content_type() == "text/html":
                    payload = part.get_payload(decode=True)
                    if payload:
                        return payload.decode(part.get_content_charset() or "utf-8", errors="ignore")
        else:
            payload = message.get_payload(decode=True)
            if payload:
                return payload.decode(message.get_content_charset() or "utf-8", errors="ignore")
        return ""


class AppleMailAdapter(BaseClientAdapter):
