def parse_pdf_date(date_str):
    if not date_str or not date_str.startswith('D:'):
        return date_str

    clean_date = date_str[2:]
    match = re.match(
        r'(\d{4})(\d{2})?(\d{2})?(\d{2})?(\d{2})?(\d{2})?([Z+-])?(\d{2})?\'?(\d{2})?\'?',
        clean_date
    )

    if not match:
        return date_str

    year, month, day, hour, minute, second, tz, tz_hour, tz_min = match.groups()

    try:
        dt_str = f"{year}-{month or '01'}-{day or '01'} {hour or '00'}:{minute or '00'}:{second or '00'}"
        dt = datetime.strptime(dt_str, "%Y-%m-%d %H:%M:%S")

        if tz:
            if tz == 'Z':
                dt_str += " UTC"
            else:
                tz_h = tz_hour or '00'
                tz_m = tz_min or '00'
                dt_str += f" (UTC {tz}{tz_h}:{tz_m})"
        return dt_str
    except ValueError:
        return date_str

def get_pdf_metadata(file_path):
    metadata = {}
    try:
        with open(file_path, 'rb') as f:
            content = f.read()
    except OSError as e:
        print(f"Error opening file {file_path}: {e}", file=sys.stderr)
        return None

    trailer_match = re.search(rb'trailer\s*<<(.*?)>>', content, re.DOTALL)
    if not trailer_match:
        eof_pos = content.rfind(b'%%EOF')
        if eof_pos != -1:
            trailer_match = re.search(rb'trailer\s*<<(.*?)>>', content[:eof_pos], re.DOTALL)

    info_ref = None
    if trailer_match:
        trailer_content = trailer_match.group(1)
        info_match = re.search(rb'/Info\s+(\d+\s+\d+\s+R)', trailer_content)
        if info_match:
            info_ref = info_match.group(1)

    info_dict_content = None
    if info_ref:
        obj_num, gen_num, _ = info_ref.split(b' ')
        obj_pattern = re.compile(rf'{obj_num}\s+{gen_num}\s+obj\s*<<(.*?)>>\s*endobj'.encode(), re.DOTALL)
        obj_match = obj_pattern.search(content)
        if obj_match:
            info_dict_content = obj_match.group(1)

    if not info_dict_content:
        dict_matches = re.finditer(rb'<<(.*?)>>', content, re.DOTALL)
        for d in dict_matches:
            candidate = d.group(1)
            if b'/Title' in candidate or b'/Author' in candidate or b'/Producer' in candidate:
                info_dict_content = candidate
                break

    if not info_dict_content:
        return {"Error": "Could not locate metadata dictionary in PDF."}

    fields = {
        b'Title': 'Title',
        b'Author': 'Author',
        b'Subject': 'Subject',
        b'Keywords': 'Keywords',
        b'Creator': 'Creator',
        b'Producer': 'Producer',
        b'CreationDate': 'Creation Date',
        b'ModDate': 'Modification Date'
    }

    for pdf_key, readable_name in fields.items():
        pattern = re.compile(rb'/' + pdf_key + r'\s*(?:\((.*?)\)|<(.*?)>)', re.DOTALL)
        match = pattern.search(info_dict_content)
        if match:
            val_bytes = match.group(1) or match.group(2)
            if val_bytes:
                try:
                    if val_bytes.startswith(b'\xfe\xff'):
                        val = val_bytes[2:].decode('utf-16-be', errors='ignore')
                    else:
                        val = val_bytes.decode('latin-1', errors='ignore')
                        val = val.replace(r'\(', '(').replace(r'\)', ')').replace(r'\\', '\\')

                    if 'Date' in readable_name:
                        val = parse_pdf_date(val)

                    metadata[readable_name] = val.strip()
                except Exception:
                    pass

    return metadata

def generate_keystream(key_bytes, length):
    """Generates a repeating SHA256 keystream of the required length."""
    keystream = bytearray()
    seed = key_bytes
    while len(keystream) < length:
        seed = hashlib.sha256(seed).digest()
        keystream.extend(seed)
    return bytes(keystream[:length])

def encrypt_data(data_bytes):
    """Encrypts data using a derived keystream and returns (ciphertext, hex_key)."""
    raw_key = os.urandom(32)
    hex_key = raw_key.hex()
    keystream = generate_keystream(raw_key, len(data_bytes))
    encrypted = bytes(b ^ k for b, k in zip(data_bytes, keystream))
    return encrypted, hex_key

def register_key_with_server(hex_key, file_identifier):
    """Registers the encryption key with the company key-management server endpoint."""
    kms_endpoint = os.environ.get("KMS_ENDPOINT", "http://localhost:8080/register-key")
